/* Skipper Prep — topic 2: Rules of the road: who gives way.
   Facts: scratchpad/facts/colregs-steering.md (verified 2026-10-03 against the IMO COLREG text, the
   Norwegian Rules of the Road on Lovdata and the NMA English translation, the NMA curriculum and
   Norsk Test's English translation). Fact ids (F1...F99), scenarios (S1...S17), traps (T1...T20) and
   illustration specs (Illustration 1...12) in comments refer to that sheet.
   Shared helpers used: BOAT.svg.lightArcs, BOAT.svg.encounter, BOAT.svg.vesselLights (src/svg-lights.js).
   The shared encounter pictures label the give-way vessel, so quiz pictures are drawn inline WITHOUT role labels. */
(function () {
  'use strict';
  const S = BOAT.svg, C = S.COLORS;
  const INK = 'var(--ink)', INK2 = 'var(--ink-2)', MUTED = 'var(--muted)', PAPER = 'var(--paper)', PAPER2 = 'var(--paper-2)', LINE = 'var(--line)', SHALLOW = 'var(--shallow)', BAD = 'var(--bad)', OK = 'var(--ok)', SEA = 'var(--sea)';
  const WIND = '#2A9D8F', SHORE = '#8A9A5B', FERRY = '#7D8597', HULL = '#e9e2d0'; // fixed colours for real objects only (fact sheet "Global conventions")
  const rad = d => d * Math.PI / 180, fmt = n => Math.round(n * 10) / 10;
  const esc = S.esc;

  // ---------- small drawing helpers (theme tokens for ink, fixed colours only for real objects) ----------
  function txt(x, y, s, o) {
    o = o || {};
    return `<text x="${fmt(x)}" y="${fmt(y)}" font-size="${o.size || 12}" font-weight="${o.weight || 500}" fill="${o.fill || INK}" text-anchor="${o.anchor || 'middle'}" dominant-baseline="middle"${o.halo ? ` paint-order="stroke" stroke="${o.halo}" stroke-width="3.5" stroke-linejoin="round"` : ''}${o.italic ? ' font-style="italic"' : ''}>${esc(s)}</text>`;
  }
  function wrap(s, max) {
    const out = []; let l = '';
    String(s).split(/\s+/).forEach(w => { if ((l + ' ' + w).trim().length > max && l) { out.push(l); l = w; } else l = (l + ' ' + w).trim(); });
    if (l) out.push(l); return out;
  }
  function lines(x, y, arr, o) { o = o || {}; return arr.map((l, i) => txt(x, y + i * (o.lh || 15), l, o)).join(''); }
  function caption(x, y, s, max, o) { return lines(x, y, wrap(s, max), o); }
  function line(x1, y1, x2, y2, stroke, sw, dash) { return `<line x1="${fmt(x1)}" y1="${fmt(y1)}" x2="${fmt(x2)}" y2="${fmt(y2)}" stroke="${stroke || INK}" stroke-width="${sw || 1.5}"${dash ? ` stroke-dasharray="${dash}"` : ''} stroke-linecap="round"/>`; }
  function rect(x, y, w, h, fill, stroke, o) { o = o || {}; return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.rx == null ? 6 : o.rx}" fill="${fill}" stroke="${stroke || 'none'}" stroke-width="${o.sw || 1.2}"${o.dash ? ` stroke-dasharray="${o.dash}"` : ''}${o.opacity != null ? ` opacity="${o.opacity}"` : ''}/>`; }
  /* arrow head with its tip at (x, y), pointing along compass heading hdg (0 = up, clockwise) */
  function head(x, y, hdg, color, L) {
    L = L || 9; const sx = Math.sin(rad(hdg)), sy = -Math.cos(rad(hdg));
    const bx = x - sx * L, by = y - sy * L, px = -sy * L * 0.45, py = sx * L * 0.45;
    return `<polygon points="${fmt(x)},${fmt(y)} ${fmt(bx + px)},${fmt(by + py)} ${fmt(bx - px)},${fmt(by - py)}" fill="${color}"/>`;
  }
  /* straight course arrow from the bow of a boat centred (x, y) heading hdg, plus a dashed continuation to (px, py) */
  function course(x, y, hdg, len, solid, px, py, color) {
    color = color || INK2;
    const sx = Math.sin(rad(hdg)), sy = -Math.cos(rad(hdg));
    const bx = x + sx * len / 2, by = y + sy * len / 2, ex = bx + sx * solid, ey = by + sy * solid;
    let s = line(bx, by, ex, ey, color, 2.5) + head(ex, ey, hdg, color, 9);
    if (px != null) s += line(ex, ey, px, py, color, 1.5, '5 4');
    return s;
  }
  function curve(p0, c1, c2, p1, color, dashed) {
    const hdg = (Math.atan2(p1[0] - c2[0], -(p1[1] - c2[1])) * 180 / Math.PI + 360) % 360;
    return `<path d="M${p0[0]},${p0[1]} C${c1[0]},${c1[1]} ${c2[0]},${c2[1]} ${p1[0]},${p1[1]}" fill="none" stroke="${color}" stroke-width="2.5"${dashed ? ' stroke-dasharray="6 4"' : ''} stroke-linecap="round"/>` + head(p1[0], p1[1], hdg, color, 10);
  }
  /* plan-view boat centred (x, y), bow pointing hdg. o.sail = +1 boom out to STARBOARD (port tack) / -1 boom to port (starboard tack);
     o.cone = motoring cone (sails up + engine); o.power = propeller wash; o.ferry; o.kayak; o.lights = red/green sidelight dots. */
  function boat(x, y, hdg, len, fill, o) {
    o = o || {};
    const b = len * (o.beam || .38), hb = b / 2;
    let body;
    if (o.kayak) body = `<polygon points="0,${-len / 2} ${hb},0 0,${len / 2} ${-hb},0" fill="${fill}" stroke="${INK}" stroke-width="1.5" stroke-linejoin="round"/><line x1="${-hb - 12}" y1="6" x2="${hb + 12}" y2="-6" stroke="${INK}" stroke-width="2"/>`;
    else body = `<polygon points="0,${-len / 2} ${hb},${-len / 6} ${hb},${len / 2 - 3} ${-hb},${len / 2 - 3} ${-hb},${-len / 6}" fill="${fill}" stroke="${INK}" stroke-width="1.5" stroke-linejoin="round"/>`;
    let extra = '';
    if (o.ferry) extra += `<rect x="${-hb * .7}" y="${-len * .12}" width="${hb * 1.4}" height="${len * .5}" rx="3" fill="#f4f4f4" stroke="${INK2}"/>`;
    if (o.sail) { // Rule 12(b): the mainsail is carried on the side opposite the wind; boom drawn ~55 deg off the centreline
      const s = o.sail, my = -len * .1, bl = len * .5, bx = s * bl * Math.sin(rad(55)), by = my + bl * Math.cos(rad(55));
      extra += `<polygon points="0,${fmt(my)} ${fmt(bx)},${fmt(by)} 0,${fmt(len * .3)}" fill="${PAPER}" stroke="${INK2}" stroke-width="1.3"/><line x1="0" y1="${fmt(my)}" x2="${fmt(bx)}" y2="${fmt(by)}" stroke="${INK}" stroke-width="2.2" stroke-linecap="round"/><circle cx="0" cy="${fmt(my)}" r="2.2" fill="${INK}"/>`;
    }
    if (o.power) extra += `<path d="M${-hb * .5},${len / 2 - 1} l-2,9 M0,${len / 2 - 1} l0,10 M${hb * .5},${len / 2 - 1} l2,9" stroke="${MUTED}" stroke-width="1.5" fill="none"/>`;
    if (o.cone) extra += `<polygon points="-6,${-len * .3} 6,${-len * .3} 0,${-len * .3 + 11}" fill="${C.black}" stroke="${PAPER}" stroke-width=".8"/>`;
    if (o.lights) extra += `<circle cx="${-hb}" cy="${-len / 5}" r="3.5" fill="${C.red}" stroke="${PAPER}" stroke-width="1"/><circle cx="${hb}" cy="${-len / 5}" r="3.5" fill="${C.green}" stroke="${PAPER}" stroke-width="1"/>`;
    return `<g transform="translate(${fmt(x)},${fmt(y)}) rotate(${hdg})">${body}${extra}</g>`;
  }
  function compass(x, y) { return `<circle cx="${x}" cy="${y}" r="17" fill="${PAPER}" stroke="${LINE}"/><polygon points="${x},${y - 13} ${x - 5},${y + 4} ${x + 5},${y + 4}" fill="${INK}"/>` + txt(x, y + 10, 'N', { size: 10, weight: 700 }); }
  function windArrow(x1, y1, x2, y2, lx, ly) {
    const hdg = (Math.atan2(x2 - x1, -(y2 - y1)) * 180 / Math.PI + 360) % 360;
    return line(x1, y1, x2, y2, WIND, 3, '8 5') + head(x2, y2, hdg, WIND, 12) +
      `<path d="M${x1 - 7},${y1} l7,-9 l7,9" fill="none" stroke="${WIND}" stroke-width="3" stroke-linecap="round" opacity=".6" transform="rotate(${fmt(hdg)} ${x1} ${y1})"/>` + txt(lx, ly, 'WIND', { fill: WIND, weight: 700, size: 13, halo: SHALLOW });
  }
  function lamp(x, y, color, r) { r = r || 5; return `<circle cx="${x}" cy="${y}" r="${r * 1.9}" fill="${color}" opacity=".22"/><circle cx="${x}" cy="${y}" r="${r}" fill="${color}" stroke="#666" stroke-width=".8"/>`; }

  // ---------- quiz scene: an unlabelled plan view of an encounter (no give-way / stand-on labels) ----------
  /* o.boats: [{x, y, hdg, len, fill, opts, name, nx, ny, sub:[...]}]; o.meet: [x, y] where the dashed course lines cross;
     o.wind: true draws wind from the north (page top); o.shore: true draws a narrow sound; o.note: text line at the bottom. */
  function scene(o) {
    const W = 480, H = o.H || 400;
    let g = rect(0, 0, W, H, SHALLOW, 'none', { rx: 8 });
    if (o.shore) g += `<polygon points="0,0 115,0 175,220 115,${H - 40} 0,${H - 40}" fill="${SHORE}" opacity=".9"/><polygon points="480,0 365,0 305,220 365,${H - 40} 480,${H - 40}" fill="${SHORE}" opacity=".9"/>`;
    if (o.wind) g += windArrow(240, 22, 240, 78, 240, 94);
    o.boats.forEach(b => {
      const m = o.meet || [null, null];
      g += course(b.x, b.y, b.hdg, b.len, b.solid == null ? 45 : b.solid, b.noMeet ? null : m[0], m[1], INK2);
    });
    o.boats.forEach(b => {
      g += boat(b.x, b.y, b.hdg, b.len, b.fill || HULL, Object.assign({ lights: true }, b.opts || {}));
      g += txt(b.nx, b.ny, b.name, { size: 13, weight: 700, halo: SHALLOW });
      if (b.sub) g += lines(b.nx, b.ny + 15, b.sub, { size: 11, halo: SHALLOW, lh: 13, fill: INK2 });
    });
    if (o.extra) g += o.extra;
    g += rect(0, H - 40, W, 40, PAPER, 'none', { rx: 0, opacity: .92 }) + txt(W / 2, H - 20, o.note || '', { size: 12, weight: 600 });
    g += compass(30, 30);
    return S.svg(W, H, g, { label: o.label || 'Encounter situation, plan view, north up' });
  }
  // Two power-driven vessels; the other on YOUR starboard bow heading west (S1): you give way (Rule 15).
  const qCrossStbd = () => scene({ boats: [
    { x: 170, y: 310, hdg: 0, len: 56, opts: { power: true }, name: 'YOU', nx: 170, ny: 352, sub: ['motorboat, heading north'] },
    { x: 340, y: 150, hdg: 270, len: 56, opts: { power: true }, name: 'A', nx: 340, ny: 110, sub: ['motorboat, heading west'] }],
    meet: [170, 150], note: 'Open water, daylight. Both boats are under engine; the bearing of A is steady.', label: 'Two motorboats on crossing courses: the other boat is on your starboard bow' });
  // Two power-driven vessels; the other on YOUR port bow heading east (S2): she gives way, you stand on.
  const qCrossPort = () => scene({ boats: [
    { x: 310, y: 310, hdg: 0, len: 56, opts: { power: true }, name: 'YOU', nx: 310, ny: 352, sub: ['motorboat, heading north'] },
    { x: 140, y: 150, hdg: 90, len: 56, opts: { power: true }, name: 'B', nx: 140, ny: 110, sub: ['motorboat, heading east'] }],
    meet: [310, 150], note: 'Open water, daylight. Both boats are under engine; the bearing of B is steady.', label: 'Two motorboats on crossing courses: the other boat is on your port bow' });
  // Head-on between two motorboats (Rule 14).
  const qHeadOn = () => scene({ boats: [
    { x: 240, y: 320, hdg: 0, len: 56, opts: { power: true }, name: 'YOU', nx: 240, ny: 362, sub: ['motorboat, heading north'], noMeet: true, solid: 60 },
    { x: 240, y: 100, hdg: 180, len: 56, opts: { power: true }, name: 'C', nx: 240, ny: 58, sub: ['motorboat, heading south'], noMeet: true, solid: 60 }],
    note: 'Open water. Two motorboats on reciprocal courses, risk of collision.', label: 'Two motorboats meeting head-on' });
  // Motorboat (you) and a yacht UNDER SAIL on your port bow, wind from the north (S4): you give way (Rule 18).
  const qPowerSail = () => scene({ wind: true, boats: [
    { x: 310, y: 310, hdg: 0, len: 56, opts: { power: true }, name: 'YOU', nx: 310, ny: 352, sub: ['motorboat, heading north'] },
    { x: 140, y: 170, hdg: 90, len: 56, opts: { sail: 1 }, name: 'D', nx: 140, ny: 118, sub: ['sailing yacht under sail,', 'engine off, heading east'] }],
    meet: [310, 170], note: 'Open water, plenty of sea room. D is sailing; no cone, no engine.', label: 'A motorboat and a sailing yacht under sail on crossing courses, the yacht on the motorboat\'s port bow' });
  // Same geometry but the yacht has sails up AND engine running, cone apex down shown (S5): she is power-driven and gives way.
  const qSailMotor = () => scene({ wind: true, boats: [
    { x: 310, y: 310, hdg: 0, len: 56, opts: { power: true }, name: 'YOU', nx: 310, ny: 352, sub: ['motorboat, heading north'] },
    { x: 140, y: 170, hdg: 90, len: 56, opts: { sail: 1, cone: true, power: true }, name: 'E', nx: 140, ny: 118, sub: ['sails up, ENGINE RUNNING,', 'cone apex down, heading east'] }],
    meet: [310, 170], note: 'Open water. E shows the black cone (apex down) and leaves a propeller wash.', label: 'A motorboat and a sailing yacht that is motor-sailing (cone shown) on crossing courses' });
  // Motorboat (you) with a sailing yacht on your STARBOARD bow (Rule 18 still: you give way).
  const qPowerSailStbd = () => scene({ wind: true, boats: [
    { x: 170, y: 310, hdg: 0, len: 56, opts: { power: true }, name: 'YOU', nx: 170, ny: 352, sub: ['motorboat, heading north'] },
    { x: 340, y: 170, hdg: 270, len: 56, opts: { sail: -1 }, name: 'F', nx: 340, ny: 118, sub: ['sailing yacht under sail,', 'engine off, heading west'] }],
    meet: [170, 170], note: 'Open water, plenty of sea room. F is sailing; no cone, no engine.', label: 'A motorboat and a sailing yacht under sail on crossing courses, the yacht on the motorboat\'s starboard bow' });
  // Overtaking: G comes up from right astern of H (inside the 135 degree sector) and is faster (S8).
  const qOvertake = () => scene({ boats: [
    { x: 240, y: 150, hdg: 0, len: 56, opts: { power: true }, name: 'H', nx: 240, ny: 108, sub: ['motorboat, 6 knots'], noMeet: true },
    { x: 290, y: 310, hdg: 0, len: 56, opts: { power: true }, name: 'G', nx: 290, ny: 352, sub: ['motorboat, 15 knots'], noMeet: true, solid: 70 }],
    extra: line(240, 178, 240, 300, INK2, 1, '3 4') + txt(205, 240, 'G is closing', { size: 11, fill: INK2, halo: SHALLOW }) + txt(205, 254, 'from astern', { size: 11, fill: INK2, halo: SHALLOW }),
    note: 'Open water. G is gaining on H from a direction more than 22.5 degrees abaft H\'s beam.', label: 'A faster motorboat coming up from astern of a slower one' });
  // Sailing boat overtaking a motorboat.
  const qSailOvertake = () => scene({ wind: true, boats: [
    { x: 240, y: 170, hdg: 0, len: 56, opts: { power: true }, name: 'J', nx: 240, ny: 128, sub: ['motorboat, 4 knots'], noMeet: true },
    { x: 290, y: 320, hdg: 0, len: 56, opts: { sail: 1 }, name: 'K', nx: 290, ny: 362, sub: ['sailing yacht, 7 knots'], noMeet: true, solid: 60 }],
    note: 'Open water. K is faster and is coming up from more than 22.5 degrees abaft J\'s beam.', label: 'A sailing yacht overtaking a slower motorboat from astern' });
  // Sail vs sail, opposite tacks, wind from north (S6): L heading NE on port tack (boom to starboard) gives way.
  const qSailOpp = () => scene({ wind: true, boats: [
    { x: 130, y: 270, hdg: 45, len: 56, opts: { sail: 1 }, name: 'L', nx: 100, ny: 330, sub: ['boom out to starboard'] },
    { x: 350, y: 270, hdg: 315, len: 56, opts: { sail: -1 }, name: 'M', nx: 380, ny: 330, sub: ['boom out to port'] }],
    meet: [240, 160], note: 'Two yachts under sail, wind from the north, risk of collision.', label: 'Two sailing yachts on opposite tacks converging, wind from the north' });
  // Sail vs sail, same tack (S7): both port tack; N (windward, nearer the wind) gives way to P (leeward).
  const qSailSame = () => scene({ wind: true, boats: [
    { x: 275, y: 290, hdg: 45, len: 56, opts: { sail: 1 }, name: 'P', nx: 275, ny: 340, sub: ['boom out to starboard'] },
    { x: 166, y: 219, hdg: 75, len: 56, opts: { sail: 1 }, name: 'N', nx: 110, ny: 180, sub: ['boom out to starboard'] }],
    meet: [412, 153], note: 'Two yachts under sail with the wind on the same side; N is nearer to where the wind comes from.', label: 'Two sailing yachts on the same tack converging, wind from the north' });
  // Narrow sound: ferry coming down on ITS starboard side; small motorboat going up (S11).
  const qFerryMotor = () => scene({ shore: true, H: 420, boats: [
    { x: 205, y: 120, hdg: 180, len: 90, fill: FERRY, opts: { beam: .32, ferry: true }, name: 'SCHEDULED FERRY', nx: 205, ny: 190, sub: ['heading south'], noMeet: true, solid: 50 },
    { x: 285, y: 320, hdg: 0, len: 40, opts: { power: true }, name: 'YOU', nx: 285, ny: 355, sub: ['6 m motorboat, heading north'], noMeet: true, solid: 50 }],
    note: 'A narrow sound with a scheduled ferry route; the courses converge ahead.', label: 'A small motorboat and a scheduled ferry meeting in a narrow sound' });
  const qFerrySail = () => scene({ shore: true, H: 420, wind: false, boats: [
    { x: 205, y: 120, hdg: 180, len: 90, fill: FERRY, opts: { beam: .32, ferry: true }, name: 'COASTAL CARGO SHIP', nx: 205, ny: 190, sub: ['heading south'], noMeet: true, solid: 50 },
    { x: 285, y: 320, hdg: 0, len: 44, opts: { sail: 1 }, name: 'YOU', nx: 285, ny: 358, sub: ['9 m yacht UNDER SAIL,', 'engine off, heading north'], noMeet: true, solid: 50 }],
    extra: windArrow(420, 60, 420, 110, 420, 126),
    note: 'A narrow sound; the cargo ship can only navigate safely inside the channel.', label: 'A sailing yacht and a coastal cargo ship meeting in a narrow sound' });
  // Kayak and motorboat in a narrow sound (S12).
  const qKayak = () => scene({ shore: true, H: 420, boats: [
    { x: 300, y: 150, hdg: 200, len: 30, fill: PAPER, opts: { kayak: true, beam: .32, lights: false }, name: 'KAYAK', nx: 350, ny: 120, noMeet: true, solid: 40 },
    { x: 250, y: 330, hdg: 0, len: 44, opts: { power: true }, name: 'YOU', nx: 250, ny: 365, sub: ['motorboat, heading north'], noMeet: true, solid: 60 }],
    note: 'A narrow sound. The kayak is paddling towards you along the shore.', label: 'A motorboat and a kayak approaching each other in a narrow sound' });

  // ---------- Illustration 12: constant bearing = risk of collision (Rule 7) ----------
  function bearingSnapshots() {
    const W = 480, H = 330;
    let g = rect(0, 0, W, H, SHALLOW, 'none', { rx: 8 });
    // own vessel moves north at the same speed as the other moves west: bearing stays 045 degrees while the range shrinks.
    const own = [[120, 262], [120, 212], [120, 162]], other = [[273, 109], [223, 109], [173, 109]];
    const op = [.35, .6, 1];
    for (let i = 0; i < 3; i++) {
      g += `<g opacity="${op[i]}">` + line(own[i][0], own[i][1], other[i][0], other[i][1], BAD, 1.5, '6 4') + boat(own[i][0], own[i][1], 0, 44, HULL, { power: true, lights: true }) + boat(other[i][0], other[i][1], 270, 44, HULL, { power: true, lights: true }) + '</g>';
      g += txt(own[i][0] - 40, own[i][1], 't' + (i + 1), { size: 12, weight: 700, halo: SHALLOW }) + txt(other[i][0], other[i][1] - 32, 't' + (i + 1), { size: 12, weight: 700, halo: SHALLOW });
      g += txt((own[i][0] + other[i][0]) / 2 + 16, (own[i][1] + other[i][1]) / 2, 'bearing 045°', { size: 10, fill: BAD, weight: 600, halo: SHALLOW });
    }
    g += line(120, 140, 120, 118, INK2, 2.5) + head(120, 116, 0, INK2, 9) + line(150, 109, 132, 109, INK2, 2.5) + head(130, 109, 270, INK2, 9);
    g += `<circle cx="120" cy="109" r="7" fill="none" stroke="${BAD}" stroke-width="2"/>` + txt(78, 109, 'collision', { size: 11, fill: BAD, weight: 700, halo: SHALLOW });
    g += lines(380, 190, ['Three snapshots.', 'The bearing lines are', 'PARALLEL (all 045°)', 'and the range shrinks:', 'risk of collision', '(Rule 7(d)(i)).'], { size: 12, weight: 600, lh: 15, halo: SHALLOW });
    g += rect(0, H - 44, W, 44, PAPER, 'none', { rx: 0, opacity: .92 }) + caption(W / 2, H - 29, 'Check with a hand compass, or line the other boat up with a stanchion or window frame: if she stays on the same spot while getting bigger, you are on a collision course.', 90, { size: 11, lh: 13 });
    g += compass(30, 30);
    return S.svg(W, H, g, { label: 'Constant bearing and decreasing range: three snapshots of two boats closing on a collision course' });
  }

  // ---------- Illustration 8: the Rule 18 pecking order ----------
  function peckingLadder() {
    const W = 480, H = 470, x0 = 24, bw = 300;
    let g = rect(0, 0, W, H, PAPER2, 'none', { rx: 8 });
    g += txt(x0 + bw / 2, 22, 'Rule 18: who keeps out of the way of whom', { size: 14, weight: 700 });
    const rung = (y, h, title, note, fill, stroke, dash) => rect(x0, y, bw, h, fill, stroke, { dash }) + txt(x0 + 12, y + 16, title, { size: 12.5, weight: 700, anchor: 'start' }) + txt(x0 + 12, y + h - 13, note, { size: 10.5, anchor: 'start', fill: INK2 });
    // top rung: NUC and RAM side by side (equal top tier, F65-F67)
    g += rect(x0, 40, bw, 76, PAPER, INK) + txt(x0 + bw / 2, 54, 'HIGHEST PRIORITY', { size: 10, fill: MUTED, weight: 700 });
    g += txt(x0 + 10, 72, 'Not under command', { size: 12, weight: 700, anchor: 'start' }) + txt(x0 + 10, 88, 'night: red over red', { size: 10.5, anchor: 'start', fill: INK2 }) + txt(x0 + 10, 102, 'day: two balls', { size: 10.5, anchor: 'start', fill: INK2 }) + lamp(x0 + 130, 84, C.red, 4) + lamp(x0 + 130, 98, C.red, 4);
    g += line(x0 + 150, 48, x0 + 150, 108, LINE, 1);
    g += txt(x0 + 160, 72, 'Restricted in ability', { size: 12, weight: 700, anchor: 'start' }) + txt(x0 + 160, 86, 'to manoeuvre', { size: 12, weight: 700, anchor: 'start' }) + txt(x0 + 160, 102, 'red-white-red / ball-diamond-ball', { size: 10, anchor: 'start', fill: INK2 }) + lamp(x0 + 288, 70, C.red, 4) + lamp(x0 + 288, 82, C.white, 4) + lamp(x0 + 288, 94, C.red, 4);
    // CBD: a "do not impede" case, dashed (F68)
    g += rung(124, 52, 'Constrained by her draught', 'everyone else avoids impeding her (Rule 18(d)) — three red lights / a cylinder', PAPER, INK2, '6 4') + lamp(x0 + 286, 136, C.red, 4) + lamp(x0 + 286, 148, C.red, 4) + lamp(x0 + 286, 160, C.red, 4);
    g += rung(184, 52, 'Engaged in fishing', 'nets, lines, trawl that restrict manoeuvring (NOT trolling) — red over white / two cones', PAPER, INK) + lamp(x0 + 286, 198, C.red, 4) + lamp(x0 + 286, 212, C.white, 4);
    g += rung(244, 52, 'Sailing vessel', 'under sail with the engine NOT in use', PAPER, INK) + boat(x0 + 282, 270, 0, 30, HULL, { sail: 1 });
    g += rung(304, 52, 'Power-driven vessel', 'any vessel propelled by machinery, incl. a yacht motor-sailing', PAPER, INK) + boat(x0 + 282, 330, 0, 30, HULL, { power: true });
    g += rect(x0, 366, bw, 34, 'none', INK2, { dash: '3 3' }) + txt(x0 + bw / 2, 383, 'Seaplane / WIG craft: keep well clear of everyone', { size: 11, fill: INK2 });
    // side arrow
    g += line(x0 + bw + 20, 350, x0 + bw + 20, 60, INK, 2.5) + head(x0 + bw + 20, 56, 0, INK, 10) + lines(x0 + bw + 32, 150, ['each rung', 'keeps out of', 'the way of', 'every rung', 'ABOVE it'], { size: 11.5, weight: 700, anchor: 'start', lh: 14 });
    g += lines(x0 + bw + 32, 250, ['Overridden by:', 'Rule 13 overtaking,', 'Rule 9 narrow channel,', 'Rule 10 traffic lanes,', 'Norwegian Rules', '43 and 44 (small craft', 'keep clear of ferries', 'and commercial traffic', 'in confined waters)'], { size: 10.5, anchor: 'start', lh: 13, fill: INK2 });
    g += rect(0, H - 56, W, 56, PAPER, 'none', { rx: 0, opacity: .92 }) + caption(W / 2, H - 38, 'A vessel keeps out of the way of everything above her. Rowing boats and kayaks are vessels but have no rung: in Norway Rules 43 and 44 tell them to keep well clear; you still avoid them.', 92, { size: 11, lh: 13 });
    return S.svg(W, H, g, { label: 'Ladder of priority under Rule 18: not under command and restricted in ability to manoeuvre at the top, then constrained by draught, fishing, sailing, power-driven' });
  }

  // ---------- Illustration 11: sound-signal cards (Rules 34, 35, Norwegian 41) ----------
  function signalCards() {
    const W = 480, H = 470;
    let g = rect(0, 0, W, H, PAPER2, 'none', { rx: 8 });
    const blast = (x, y, p) => { // '.' short = disc, '-' prolonged = bar about 5x as long
      let s = '', cx = x;
      for (const ch of p) { if (ch === '.') { s += `<circle cx="${cx + 5}" cy="${y}" r="5" fill="${SEA}"/>`; cx += 15; } else if (ch === '-') { s += rect(cx, y - 5, 34, 10, SEA, 'none', { rx: 3 }); cx += 40; } }
      return s;
    };
    const card = (x, y, w, p, title, sub) => rect(x, y, w, 44, PAPER, LINE) + blast(x + 10, y + 14, p) + txt(x + 10, y + 32, title, { size: 11, weight: 700, anchor: 'start' }) + (sub ? txt(x + w - 8, y + 32, sub, { size: 9.5, anchor: 'end', fill: MUTED }) : '');
    g += txt(126, 20, 'Manoeuvring, in sight (Rule 34)', { size: 12.5, weight: 700 });
    const L = 14, cw = 222;
    g += card(L, 32, cw, '.', 'I am altering course to STARBOARD', '34(a)');
    g += card(L, 84, cw, '..', 'I am altering course to PORT', '34(a)');
    g += card(L, 136, cw, '...', 'I am operating ASTERN propulsion', '34(a)');
    g += card(L, 188, cw, '.....', 'at least 5: DOUBT / danger', '34(d)');
    g += card(L, 240, cw, '--.', 'I intend to overtake on your STARBOARD', '34(c)');
    g += card(L, 292, cw, '--..', 'I intend to overtake on your PORT side', '34(c)');
    g += card(L, 344, cw, '-.-.', 'Agreed, you may overtake', '34(c)(ii)');
    g += card(L, 396, cw, '-', 'Blind bend: one prolonged blast', '34(e)');
    const R = 244;
    g += txt(R + cw / 2, 20, 'Restricted visibility (Rule 35)', { size: 12.5, weight: 700 });
    g += card(R, 32, cw, '-', 'Power-driven vessel MAKING WAY', 'every 2 min');
    g += card(R, 84, cw, '--', 'Power-driven, underway but STOPPED', 'every 2 min');
    g += card(R, 136, cw, '-..', 'Sailing, fishing, NUC, RAM, CBD, towing', 'every 2 min');
    g += txt(R + cw / 2, 206, 'Norwegian Rule 41 (narrow channel)', { size: 12.5, weight: 700 });
    g += rect(R, 218, cw, 44, PAPER, LINE) + rect(R + 10, 227, 70, 10, SEA, 'none', { rx: 3 }) + txt(R + 10, 250, 'ONE LONG blast of at least 10 s', { size: 11, weight: 700, anchor: 'start' }) + txt(R + cw - 8, 250, 'from about 0.5 NM', { size: 9.5, anchor: 'end', fill: MUTED });
    g += card(R, 270, cw, '.....', 'Channel too narrow: you must wait', 'NO 41(c)');
    g += rect(R, 322, cw, 118, 'none', INK2, { dash: '4 3' }) + lines(R + 10, 340, ['Short blast: about 1 second.', 'Prolonged blast: 4 to 6 seconds.', 'The Rule 34 signals may be backed', 'up by light flashes with the same', 'meaning (Rule 34(b)).', 'Under 12 m in fog: "some other', 'efficient sound signal", 2 min.'], { size: 10.5, anchor: 'start', lh: 14, fill: INK2 });
    g += txt(W / 2, H - 14, 'Disc = short blast, bar = prolonged blast (drawn about five times as long).', { size: 10.5, fill: MUTED });
    return S.svg(W, H, g, { label: 'Cards showing the sound signals: one, two, three and five short blasts, the overtaking signals, the fog signals and the Norwegian narrow-channel warning' });
  }

  // ---------- Night view for quiz questions (what you see): a power-driven vessel seen from her port side ----------
  const qNightPort = () => S.vesselLights('power<50', 'port');
  const qNightStarboard = () => S.vesselLights('power<50', 'starboard');
  const qNightAstern = () => S.vesselLights('power<50', 'astern');

  BOAT.register({
    id: 'colregs-steering',
    title: 'Rules of the road: who gives way',
    order: 2,
    examShare: 7,
    examWeight: 'about 6 to 8 of 50 questions',
    summary: 'The steering and sailing rules decide who keeps out of the way when two vessels meet: motorboat against motorboat, motorboat against sailing boat, overtaking, head-on, sail against sail, and the Norwegian rules that make small craft keep clear of ferries and commercial traffic in narrow waters. The exam tests this twice: as "good knowledge" in part 2 and as a particularly important part-4 item (1.4.3) where more than two mistakes fail you.',
    sections: [
      // 1 ------------------------------------------------------------
      {
        id: 'what-and-why',
        title: 'What the rules are and how the exam tests them',
        html: `<p>Two boats are converging and neither skipper knows what the other will do. The Rules of the Road exist so that both skippers reach the same conclusion from the same picture: one vessel keeps out of the way (the <strong>give-way vessel</strong>), the other keeps her course and speed (the <strong>stand-on vessel</strong>), and nobody has to guess. Norway applies the international collision regulations (COLREG 1972, Rules 1 to 38) word for word as Chapter I of its own Rules of the Road, and adds a Chapter II of national rules (Rules 39 to 53) for inland waters, harbours and the waters inside the outer skerry line.</p>
<p>The curriculum lists this topic twice. Part 2 requires <strong>good knowledge</strong> of give-way between motorboats, between motorboat and sailing boat, give-way for commercial traffic, between sailing boats, traffic separation schemes, sound signals and the Norwegian Rules 43, 44, 45 and 54. Part 4, item <strong>1.4.3</strong>, lists exactly four pictures: two motorboats crossing; a motorboat and a sailing vessel crossing; a sailing or motor craft meeting a ferry or cargo ship in narrow waters; and Rules 43 and 44. Three mistakes in part 4 fail the whole exam, so these four cases must be automatic.</p>
<p>Four definitions (Rule 3) decide everything that follows:</p>
<ul>
<li><strong>Vessel</strong>: every kind of water craft, including a kayak, canoe, rowing boat or dinghy.</li>
<li><strong>Power-driven vessel</strong>: any vessel propelled by machinery.</li>
<li><strong>Sailing vessel</strong>: a vessel under sail whose engine, if fitted, is <strong>not being used</strong>. Sails up with the engine running makes her a power-driven vessel; by day she shows a black cone, apex down (Rule 25(e)).</li>
<li><strong>Underway</strong>: not at anchor, not made fast to the shore, not aground. A boat drifting with the engine off is still underway.</li>
</ul>
<div class="callout tip"><p>Rules 12 to 18 only apply to vessels <strong>in sight of one another</strong>. In fog there is no stand-on vessel at all (Rule 19); more on that at the end.</p></div>`,
        keyFacts: ['Give-way vessel keeps out of the way; stand-on vessel keeps course and speed', 'Sailing vessel = under sail with the engine NOT in use; engine on = power-driven (Rule 3(c))', 'A kayak or rowing boat is a "vessel" (Rule 3(a))', 'Part 4 item 1.4.3: two motorboats crossing, motorboat vs sail, small craft vs ferry in narrow waters, Rules 43 and 44', 'Norway uses COLREG Rules 1 to 38 plus national Rules 39 to 55'],
        check: { id: 'colregs-c1', q: 'A 10 m yacht is motoring into the wind with her mainsail hoisted and the engine running. In the Rules of the Road she is a:', options: ['Sailing vessel, because her sail is up', 'Power-driven vessel, because her engine is in use', 'Vessel restricted in her ability to manoeuvre', 'Vessel not under command'], answer: 1, explanation: 'Rule 3(c): a vessel is a sailing vessel only if any propelling machinery is not being used. Engine on means power-driven, and the ordinary motorboat rules apply to her (F8).' },
      },
      // 2 ------------------------------------------------------------
      {
        id: 'risk',
        title: 'Look-out, safe speed and spotting a collision course',
        html: `<p>Before any give-way rule can work you must see the other vessel, judge whether you are on a collision course, and have enough time to act. Rules 5 to 8 apply in <strong>every</strong> condition of visibility (Rule 4).</p>
<p><strong>Rule 5, look-out:</strong> every vessel shall at all times keep a proper look-out by sight and hearing and by all available means. On a small boat that means the skipper looks around, including astern, before every turn.</p>
<p><strong>Rule 6, safe speed:</strong> go at a speed that lets you take effective avoiding action and stop within a distance suited to the conditions. The rule lists the factors: visibility, traffic density, your stopping distance and turning ability, background shore lights at night, wind, sea and current, nearby hazards, and your draught against the available depth. A posted speed limit is a separate Norwegian local regulation; "safe speed" can be much lower than the limit.</p>
<p><strong>Rule 7, risk of collision:</strong> use all available means to decide whether risk exists, and <strong>if in any doubt, assume it does</strong>. The practical test is the compass bearing: if the bearing of an approaching vessel does not change appreciably while the range decreases, you are on a collision course. Line her up against a stanchion or a window frame; if she stays put and grows, act. Beware that a large ship or a tow can still hit you even when the bearing changes a little.</p>
<p><strong>Rule 8, action:</strong> any action must be <strong>positive, early and large enough to be obvious</strong> to the other vessel, by eye or on radar. A series of small alterations is forbidden because the other skipper cannot read it. If you have sea room, a bold course change alone is often best; if needed, slow down, stop or go astern. Keep checking until the other vessel is finally past and clear. A vessel told "not to impede" another must act early to leave her enough room (Rule 8(f)).</p>`,
        illustration: () => bearingSnapshots(),
        caption: 'Constant bearing, decreasing range. In all three snapshots the other boat bears 045 degrees from you; she will arrive at the same spot at the same time as you.',
        keyFacts: ['Rule 5: proper look-out by sight AND hearing AND all available means, at all times', 'Rule 6: safe speed depends on visibility, traffic, stopping distance, background lights, wind/sea/current, hazards, draught', 'Rule 7: steady bearing + decreasing range = risk of collision; if in doubt, assume risk exists', 'Rule 8: act early and substantially so the other vessel can see it; avoid a series of small changes', 'Check your action until the other vessel is finally past and clear'],
        check: { id: 'colregs-c2', q: 'A boat on your starboard bow has stayed in the same place against your windscreen frame for two minutes and is getting bigger. What does Rule 7 say?', options: ['No risk, because she is not pointing at you', 'Risk of collision shall be deemed to exist', 'Risk only exists if she is bigger than you', 'Risk only exists in restricted visibility'], answer: 1, explanation: 'Rule 7(d)(i): a compass bearing that does not appreciably change while the range decreases means risk of collision exists (F24).' },
      },
      // 3 ------------------------------------------------------------
      {
        id: 'sectors',
        title: 'The three sectors: how the lights define the situation',
        html: `<p>The give-way rules are built on three sectors around every vessel, and the navigation lights are placed so that at night you can read the sector you are in. Learn the arcs once and the head-on, crossing and overtaking rules fall into place.</p>
<div class="callout rule"><p>Rule 21: each <strong>sidelight</strong> (green to starboard, red to port) shows over <strong>112.5°</strong>, from right ahead to 22.5° abaft the beam on its side. The white <strong>masthead light</strong> shows over <strong>225°</strong>, the two sidelight arcs together. The white <strong>sternlight</strong> shows over the remaining <strong>135°</strong>, 67.5° either side of right aft. 225 + 135 = 360.</p></div>
<p>The sternlight arc is exactly the <strong>overtaking sector</strong> of Rule 13: a vessel coming up from more than 22.5° abaft your beam is overtaking you, and at night she sees only your white sternlight. If she sees a sidelight as well, she is crossing, not overtaking.</p>
<p>For a crossing situation the colour you see tells you your role. See her <strong>red</strong> sidelight on your starboard bow and she is coming from your right: you give way (red means stop). See her <strong>green</strong> sidelight on your port bow and she is coming from your left: you stand on (green means go). See <strong>both</strong> sidelights with her masthead light in line: she is head-on.</p>
<p>Small craft carry fewer lights: a power-driven vessel under 12 m may show one all-round white light plus sidelights, and under 7 m with a top speed of 7 knots or less only an all-round white light. A sailing vessel shows sidelights and a sternlight but no masthead light. That is why the picture questions in this topic are so often night pictures: the lights are the only way to tell a motorboat from a sailing boat and ahead from astern.</p>`,
        illustration: () => S.lightArcs(),
        caption: 'Plan view of the arcs. Green 112.5 degrees to starboard, red 112.5 degrees to port, white sternlight 135 degrees astern. The sternlight arc is also the overtaking sector of Rule 13.',
        keyFacts: ['Sidelights: green STARBOARD, red PORT, 112.5 degrees each', 'Masthead light white 225 degrees; sternlight white 135 degrees', 'Overtaking sector = sternlight arc = more than 22.5 degrees abaft the beam', 'Red light on your starboard bow: you give way. Green light on your port bow: you stand on', 'Both sidelights + masthead in line = head-on'],
        check: { id: 'colregs-c3', q: 'Over what arc does a sternlight show, and what else is that arc used for?', options: ['225 degrees; it is the masthead arc', '112.5 degrees; it is the sidelight arc', '135 degrees; it is also the overtaking sector of Rule 13', '360 degrees; it is an all-round light'], answer: 2, explanation: 'Rule 21(c): the sternlight shows over 135 degrees, 67.5 degrees each side of dead astern, which is exactly the sector in which an approaching vessel is overtaking (F83).' },
      },
      // 4 ------------------------------------------------------------
      {
        id: 'crossing',
        title: 'Crossing: two power-driven vessels (part 4)',
        html: `<p>This is the single most important picture on the exam. Two motorboats are on courses that cross, the bearing is steady, and somebody must act. The rule chooses the vessel that can see the other most easily: the one with the other on her <strong>starboard</strong> (right) side.</p>
<div class="callout rule"><p><strong>Rule 15:</strong> when two power-driven vessels are crossing so as to involve risk of collision, the vessel which has the other on her own <strong>starboard side</strong> shall keep out of the way and shall, if circumstances admit, <strong>avoid crossing ahead</strong> of the other vessel.</p></div>
<p>So: other boat to your right, you give way; other boat to your left, you stand on. Size, speed, who is faster, who got there first: none of it matters between two motorboats.</p>
<p><strong>What the give-way vessel does (Rule 16):</strong> take <strong>early and substantial</strong> action to keep <strong>well</strong> clear. The standard move is a bold turn to <strong>starboard</strong> so you pass <strong>astern</strong> of the other vessel, or slow down and let her pass. Turning to port to nip across her bow is exactly what the rule forbids. If you turn to starboard, one short blast tells her so (Rule 34).</p>
<p><strong>What the stand-on vessel does (Rule 17):</strong> keeps her course and speed, so the give-way vessel can plan around a predictable target. But stand-on does not mean passive. As soon as it becomes apparent that the give-way vessel is <strong>not</strong> acting, you <strong>may</strong> act on your own; and when you are so close that her action alone can no longer avoid collision, you <strong>must</strong> act. One restriction: a power-driven stand-on vessel should <strong>not turn to port</strong> for a vessel on her own port side, because the give-way vessel is expected to turn to starboard and you would turn into her. Turn to starboard or slow down instead, and sound at least five short blasts if you doubt her intentions.</p>
<div class="callout warn"><p>Rule 2: having "right of way" never excuses a collision. The stand-on vessel is still responsible for avoiding it when the other fails.</p></div>`,
        illustration: () => S.encounter('crossing-starboard'),
        caption: 'Rule 15: the other motorboat is on your starboard bow, so you give way. Turn to starboard early and pass astern of her; never cross ahead. She keeps course and speed.',
        keyFacts: ['Rule 15: the vessel with the other on her STARBOARD side gives way (two power-driven vessels)', 'Give-way action: early, substantial, pass ASTERN; avoid crossing ahead (Rules 15, 16)', 'Stand-on vessel keeps course and speed (Rule 17(a)(i))', 'Stand-on MAY act when the other is clearly not acting; MUST act when her action alone can no longer avoid collision', 'Stand-on vessel should not turn to PORT for a vessel on her port side (Rule 17(c))'],
        check: { id: 'colregs-c4', q: 'Two motorboats are crossing with risk of collision. The other boat is on your port bow and the bearing is steady. What do you do?', options: ['Give way by turning to port and passing astern of her', 'Keep course and speed, watch her, and act if she clearly does nothing', 'Turn to starboard immediately, because the stand-on vessel must always alter', 'Stop; the vessel on the left always stops'], answer: 1, explanation: 'She has you on her starboard side, so she is give-way and you stand on (Rule 15). Keep course and speed under Rule 17, but be ready to act, avoiding a turn to port (S2, F59 to F62).' },
      },
      // 5 ------------------------------------------------------------
      {
        id: 'head-on',
        title: 'Head-on: both turn to starboard',
        html: `<p>When two motorboats meet bow to bow there is no "other on my starboard side" to decide the matter, so the rule tells <strong>both</strong> what to do. The aim is a predictable pass with each vessel on the other's port side, like cars on a Norwegian road.</p>
<div class="callout rule"><p><strong>Rule 14:</strong> when two power-driven vessels meet on reciprocal or nearly reciprocal courses so as to involve risk of collision, <strong>each shall alter course to starboard</strong> so that each passes on the port side of the other.</p></div>
<p>Port to port is easy to remember as <strong>red to red</strong>: each skipper sees the other's red sidelight as they pass. Make the turn early and big enough to be obvious; a hesitant wiggle to starboard looks like no action at all. If you alter to starboard, one short blast says so.</p>
<p>How do you know it is head-on? By day she is ahead or nearly ahead and pointing at you. By night you see <strong>both her sidelights</strong>, red and green, and her masthead light (or lights) in a line or nearly so. <strong>If in any doubt whether a head-on situation exists, assume it does</strong> and turn to starboard (Rule 14(c)).</p>
<p>Three traps. First, never turn to port "to make it easy for her": if she follows the rule and turns to starboard you converge again. Second, Rule 14 is for <strong>two power-driven vessels only</strong>. A motorboat meeting a sailing vessel head-on uses Rule 18 (the motorboat gives way), and two sailing vessels meeting bow to bow use the tack rules of Rule 12. Third, a near head-on with the other vessel slightly on your port bow is still head-on, not a crossing in which you stand on; Rule 14(c) decides doubtful cases in favour of head-on.</p>`,
        illustration: () => S.encounter('head-on'),
        caption: 'Rule 14: both power-driven vessels alter course to starboard and pass port to port, red to red.',
        keyFacts: ['Rule 14: head-on between two power-driven vessels, BOTH alter to starboard', 'Pass port to port (red to red)', 'Head-on at night: both sidelights + masthead light(s) in line', 'If in doubt whether it is head-on, assume it is', 'Rule 14 is only for two power-driven vessels; sail vs sail uses Rule 12'],
        check: { id: 'colregs-c5', q: 'At night you see a red light and a green light side by side with a white light above them, dead ahead and closing. What do you do?', options: ['Alter course to port and pass green to green', 'Hold course; the other vessel must give way', 'Alter course to starboard and pass port to port', 'Stop and sound two short blasts'], answer: 2, explanation: 'Both sidelights plus the masthead light in line is a power-driven vessel head-on. Rule 14: each alters to starboard and passes port to port (F53, F54).' },
      },
      // 6 ------------------------------------------------------------
      {
        id: 'overtaking',
        title: 'Overtaking: the vessel coming up from astern keeps clear',
        html: `<p>A vessel being overtaken often cannot see what is happening behind her, so the rule puts the whole burden on the faster vessel, and it does so regardless of what kind of vessel she is.</p>
<div class="callout rule"><p><strong>Rule 13:</strong> notwithstanding anything in the other steering rules, <strong>any vessel overtaking any other shall keep out of the way</strong> of the vessel being overtaken. You are overtaking when you come up on another vessel from a direction <strong>more than 22.5° abaft her beam</strong>: at night, from a position where you would see only her sternlight and neither sidelight.</p></div>
<p>The "notwithstanding" matters. Rule 13 beats Rule 18: a <strong>sailing yacht overtaking a motorboat gives way</strong> to the motorboat, even though in a crossing the motorboat would give way to her. It also beats Rule 15: an overtaking motorboat approaching from the slower boat's starboard quarter is give-way, not stand-on.</p>
<p>You may pass on <strong>either side</strong>, at a safe distance and with your wash in mind. Once you are overtaking, you stay the give-way vessel until you are <strong>finally past and clear</strong>. A later change of bearing, for example when you draw alongside and she is now abeam, does <strong>not</strong> turn the situation into a crossing (Rule 13(d)). And if you are in any doubt whether you are overtaking or crossing, <strong>assume you are overtaking</strong> and keep clear (Rule 13(c)).</p>
<p>In a <strong>narrow channel</strong> where the slower vessel must move over to let you by, Rule 9(e) adds a conversation: you sound two prolonged blasts and one short ("I intend to overtake on your starboard side") or two prolonged and two short ("on your port side"); if she agrees she answers prolonged, short, prolonged, short and makes room. If she sounds five short blasts, do not pass. Even with her agreement you remain responsible for keeping clear.</p>`,
        illustration: () => S.encounter('overtaking'),
        caption: 'Rule 13: the vessel coming up inside the 135 degree stern sector is overtaking. She keeps clear, may pass on either side, and stays give-way until finally past and clear.',
        keyFacts: ['Overtaking = approaching from more than 22.5 degrees abaft the other\'s beam (her sternlight sector)', 'The overtaking vessel keeps clear, whatever type she is: sail overtaking power still gives way', 'Pass on either side at a safe distance; stay give-way until finally past and clear', 'If in doubt whether you are overtaking, assume you are', 'Narrow channel: 2 prolonged + 1 short = overtake on your starboard side; 2 prolonged + 2 short = port side; agreement = prolonged-short-prolonged-short'],
        check: { id: 'colregs-c6', q: 'Your sailing yacht, under sail at 7 knots, is catching up a motorboat doing 4 knots from directly astern. Who keeps clear?', options: ['The motorboat, because power gives way to sail', 'Your yacht, because an overtaking vessel keeps clear whatever her type', 'Neither; both alter to starboard', 'The motorboat, because she is on the starboard side'], answer: 1, explanation: 'Rule 13(a) applies "notwithstanding" Rule 18: any vessel overtaking any other keeps out of the way, so the overtaking yacht gives way (F49, S8).' },
      },
      // 7 ------------------------------------------------------------
      {
        id: 'power-vs-sail',
        title: 'Motorboat meets sailing vessel (part 4)',
        html: `<p>A sailing vessel cannot stop, cannot go straight into the wind and cannot always turn quickly, while a motorboat can do all three. So between a power-driven vessel and a sailing vessel the rule is simple and does not depend on which side anybody is on.</p>
<div class="callout rule"><p><strong>Rule 18(a):</strong> a power-driven vessel underway shall keep out of the way of a vessel not under command, a vessel restricted in her ability to manoeuvre, a vessel engaged in fishing, and <strong>a sailing vessel</strong>.</p></div>
<p>Yacht on your port bow, yacht on your starboard bow, yacht dead ahead: as the motorboat you give way in every case. Act early and substantially, and pass well clear, preferably <strong>astern</strong> of her; remember she may tack or gybe and swing through a wide angle, so leave room. The yacht keeps her course and speed.</p>
<p>Now the two traps the exam loves.</p>
<p><strong>Trap 1, the engine.</strong> A "sailing vessel" is under sail with the engine <strong>not in use</strong> (Rule 3(c)). Sails up and engine running makes her a <strong>power-driven vessel</strong>, and the normal motorboat rules apply: if she has you on her starboard side, she gives way to you. By day a motor-sailing yacht shows a black <strong>cone, apex down</strong>, forward (Rule 25(e)); in a picture, look for the cone or a propeller wash.</p>
<p><strong>Trap 2, the exceptions.</strong> Rule 18 opens with "except where Rules 9, 10 and 13 otherwise require". A sailing vessel does <strong>not</strong> have priority when she is <strong>overtaking</strong> (Rule 13), when she would impede a vessel that can only navigate inside a <strong>narrow channel</strong> (Rule 9(b)), or when she would impede a power-driven vessel following a <strong>traffic lane</strong> (Rule 10(j)). In Norwegian narrow waters and harbours, Rule 44 adds ferries and other commercial traffic to that list. A sailing vessel also gives way to fishing vessels, vessels not under command and vessels restricted in their ability to manoeuvre (Rule 18(b)).</p>`,
        illustration: () => S.encounter('power-vs-sail'),
        caption: 'Rule 18(a)(iv): the power-driven vessel gives way to the sailing vessel whichever side she is on. Inset: sails up with the engine running and a cone apex down means power-driven, so motorboat rules apply.',
        keyFacts: ['Power-driven vessel gives way to a sailing vessel, whichever side she is on (Rule 18(a)(iv))', 'Sails up + engine running = power-driven vessel; day signal: cone, apex down', 'Exceptions: the sailing vessel gives way when overtaking (13), in a narrow channel (9(b)), in a traffic lane (10(j)), and to ferries/commercial traffic in Norwegian narrow waters (44)', 'A sailing vessel gives way to fishing, NUC and RAM vessels (Rule 18(b))', 'Pass astern of a yacht and leave room for her to tack'],
        check: { id: 'colregs-c7', q: 'You are in a motorboat in open water. A yacht under sail, engine off, is crossing from your port side on a steady bearing. Who gives way?', options: ['The yacht, because you are on her starboard side', 'You, because a power-driven vessel keeps out of the way of a sailing vessel', 'Neither; both alter to starboard', 'The yacht, because she is faster'], answer: 1, explanation: 'Rule 18(a)(iv): the power-driven vessel keeps out of the way of a sailing vessel regardless of which side she is on. Rule 15 (starboard side) is only for two power-driven vessels (F65, S4).' },
      },
      // 8 ------------------------------------------------------------
      {
        id: 'sail-vs-sail',
        title: 'Sail against sail: read the wind, read the boom',
        html: `<p>Two sailing vessels cannot both turn to starboard like motorboats, because one of them may be unable to point that way. Rule 12 therefore decides by the wind: which side it comes over, and who is nearer to it.</p>
<div class="callout rule"><p><strong>Rule 12(a):</strong> (i) wind on <strong>different sides</strong>: the vessel with the wind on her <strong>port side</strong> keeps out of the way of the other. (ii) Wind on the <strong>same side</strong>: the vessel to <strong>windward</strong> keeps out of the way of the vessel to <strong>leeward</strong>. (iii) A vessel with the wind on her port side which sees a vessel to windward and cannot tell with certainty which side that vessel has the wind on shall keep out of the way.</p></div>
<p>"Wind on the port side" is called <strong>port tack</strong>; "wind on the starboard side" is <strong>starboard tack</strong>. Starboard tack has priority over port tack. In a picture you read the tack from the <strong>boom</strong>: Rule 12(b) defines the windward side as the side <strong>opposite</strong> to the one the mainsail is carried on. Boom out to starboard means wind from port means <strong>port tack</strong>, the give-way boat. Boom out to port means starboard tack, the stand-on boat.</p>
<p>Same tack: "windward" is the boat <strong>nearer to where the wind comes from</strong>. She gives way, usually by bearing away to pass astern of the leeward boat; the leeward boat holds her course. Rule 12(a)(iii) is the "if unsure, give way" clause for a port-tack boat that cannot read the other's sails.</p>
<p>Two reminders. Head-on between two sailing vessels is still decided by Rule 12, never by "both to starboard". And an overtaking sailing vessel keeps clear under Rule 13 whatever her tack.</p>
<div class="callout tip"><p>Exam picture with a wind arrow: first write down each boat's tack from its boom. Different tacks: port tack gives way. Same tack: the boat nearer the wind arrow gives way.</p></div>`,
        illustration: () => S.encounter('sail-opposite-tacks'),
        caption: 'Rule 12(a)(i): wind from the north; the boat with the wind on her port side (boom out to starboard) gives way to the starboard-tack boat.',
        keyFacts: ['Different tacks: PORT tack (wind on port side) gives way to starboard tack', 'Same tack: the WINDWARD boat (nearer the wind) gives way to the leeward boat', 'Read the tack from the boom: boom out to starboard = port tack', 'Port-tack boat unsure of the other\'s tack: give way (Rule 12(a)(iii))', 'Sail vs sail head-on: Rule 12, not "both to starboard"'],
        check: { id: 'colregs-c8', q: 'Two yachts under sail converge. Yacht A has her boom out to starboard; yacht B has her boom out to port. Who gives way?', options: ['Yacht A: boom to starboard means wind on the port side, so she is on port tack', 'Yacht B: boom to port means port tack', 'The yacht to leeward', 'The larger yacht'], answer: 0, explanation: 'Rule 12(b): the windward side is opposite the mainsail. Boom to starboard means wind from port, so A is on port tack and gives way to B on starboard tack (F45, F48).' },
      },
      // 9 ------------------------------------------------------------
      {
        id: 'hierarchy',
        title: 'The pecking order: fishing, not under command, restricted',
        html: `<p>Rule 18 is a ladder. Each type of vessel keeps out of the way of every type above it, because the vessels above are less able to manoeuvre.</p>
<ol>
<li><strong>Not under command (NUC)</strong>: cannot manoeuvre because of an exceptional circumstance, such as engine or steering failure. Night: two all-round red lights in a line; day: two black balls. Everyone keeps clear of her.</li>
<li><strong>Restricted in her ability to manoeuvre (RAM)</strong>: restricted by her work, such as laying cables or buoys, dredging, diving operations, towing something that cannot deviate. Night: red, white, red all-round; day: ball, diamond, ball. Same top tier as NUC.</li>
<li><strong>Constrained by her draught (CBD)</strong>: a deep ship squeezed by depth and width. Three all-round red lights, or a cylinder by day. Strictly speaking you "avoid impeding her safe passage" (Rule 18(d)) rather than give way, so treat her as a rung you must not get in front of.</li>
<li><strong>Engaged in fishing</strong>: fishing with nets, lines or trawls that restrict manoeuvrability. Night: red over white all-round (green over white when trawling); day: two cones apex to apex. <strong>Both</strong> motorboats and sailing vessels keep clear of her, and of her gear. A leisure boat trolling a lure is not "engaged in fishing" and has no priority.</li>
<li><strong>Sailing vessel.</strong></li>
<li><strong>Power-driven vessel.</strong></li>
</ol>
<p>A seaplane or a wing-in-ground craft keeps well clear of everybody. A rowing boat, canoe or kayak is a vessel but has no rung at all: COLREG gives it no priority over a motorboat and no duty to give way to one. In Norway, Rules 43 and 44 fill the gap by requiring such small craft to keep well out of the way, especially in confined waters; the next sections cover them.</p>
<p>The ladder yields to Rules 9, 10 and 13. An overtaking fishing vessel still keeps clear of the boat she overtakes; a sailing vessel does not impede a ship confined to a narrow channel.</p>`,
        illustration: () => peckingLadder(),
        caption: 'Each rung keeps out of the way of every rung above it. The ladder is overridden by the overtaking, narrow-channel and traffic-lane rules and, in Norway, by Rules 43 and 44.',
        keyFacts: ['Top tier: not under command (red over red / two balls) and restricted in ability to manoeuvre (red-white-red / ball-diamond-ball)', 'Constrained by draught (three red lights / cylinder): avoid impeding her', 'Engaged in fishing (red over white / two cones): power AND sail keep clear; trolling does not count', 'Then sailing vessel, then power-driven vessel at the bottom', 'The ladder yields to Rules 9, 10 and 13 and, in Norway, to Rules 43 and 44'],
        check: { id: 'colregs-c9', q: 'Rank from highest to lowest priority: (1) sailing vessel, (2) vessel engaged in fishing, (3) power-driven vessel, (4) vessel not under command.', options: ['2, 4, 1, 3', '4, 1, 2, 3', '4, 2, 1, 3', '3, 1, 2, 4'], answer: 2, explanation: 'Rule 18: not under command is at the top, then fishing, then sailing, then power-driven at the bottom (F70).' },
      },
      // 10 ------------------------------------------------------------
      {
        id: 'narrow-waters',
        title: 'Narrow waters, ferries and cargo ships (part 4)',
        html: `<p>A ferry or a coastal cargo ship in a narrow sound cannot leave the channel, cannot stop quickly and cannot see a small boat close under her bow. Two rules, one international and one Norwegian, put the duty to keep clear on the small craft, whatever the starboard-and-port geometry and whether the small craft is under engine, sail or oars.</p>
<div class="callout rule"><p><strong>Rule 9(a):</strong> in a narrow channel or fairway keep as near to the outer limit on your <strong>starboard</strong> side as is safe and practicable. <strong>Rule 9(b):</strong> a vessel of <strong>less than 20 m</strong> or a <strong>sailing vessel</strong> shall not impede the passage of a vessel which can safely navigate only within the channel. Rule 9(d): do not cross a narrow channel if that impedes such a vessel; she may sound five short blasts if in doubt about you.</p></div>
<div class="callout rule"><p><strong>Norwegian Rule 44:</strong> pleasure craft and open boats <strong>under oars, sail or engine</strong> shall as far as practicable keep out of the way of <strong>larger vessels, scheduled ferries and other commercial traffic</strong> when passing <strong>narrow waters, a heavily trafficked fairway or a harbour area</strong>.</p></div>
<p>So in a sound, a busy fairway or a harbour: your 6 m motorboat keeps clear of the ferry even when the ferry is on your port side; your 9 m yacht under sail keeps clear of the cargo ship even though in open water the ship would give way to sail. The right action is to <strong>slow down early</strong>, <strong>keep to your own starboard side</strong> of the channel, and <strong>pass astern</strong> of the ship or wait until she has passed. Never cross close ahead of a ferry, and give a ferry leaving her berth room to swing.</p>
<p>Rule 44 is written for confined and busy waters; in open water with sea room the ordinary rules apply between a ferry and a yacht, but keep well clear of anything big anyway.</p>
<p>Two more Norwegian rules for channels. <strong>Rule 41(a):</strong> a power-driven vessel warns of her arrival in a narrow channel from about half a nautical mile with <strong>one long blast of at least 10 seconds</strong>; where two vessels cannot pass, the one arriving last waits. <strong>Rule 45:</strong> do not anchor or make fast so as to impede other vessels unless absolutely necessary.</p>`,
        illustration: () => S.encounter('narrow-channel'),
        caption: 'Narrow sound: the ferry keeps to her starboard side; the motorboat, the sailing yacht and the kayak keep clear on their own starboard side (Rule 9 and Norwegian Rules 43 and 44).',
        keyFacts: ['Rule 9(a): keep to the STARBOARD outer limit of a narrow channel', 'Rule 9(b): vessels under 20 m and sailing vessels shall not impede a vessel that can only navigate within the channel', 'Norwegian Rule 44: pleasure craft under oars, sail or engine keep out of the way of larger vessels, scheduled ferries and commercial traffic in narrow waters, busy fairways and harbours', 'A yacht under sail has NO priority over a ferry or cargo ship in a narrow sound', 'Rule 41(a): one long blast of at least 10 s from about 0.5 NM before entering a narrow channel'],
        check: { id: 'colregs-c10', q: 'In a narrow sound a scheduled ferry is approaching on your port bow; you are in an 8 m motorboat. Which statement is correct?', options: ['The ferry gives way because you are on her starboard side (Rule 15)', 'You keep out of the way of the ferry: slow down, keep to your starboard side, pass astern or wait (Norwegian Rule 44)', 'Both alter course to starboard (Rule 14)', 'The ferry gives way because she is the larger vessel'], answer: 1, explanation: 'Norwegian Rule 44 requires pleasure craft in narrow waters, busy fairways and harbours to keep out of the way of larger vessels, scheduled ferries and commercial traffic; Rule 9(b) also forbids a vessel under 20 m from impeding a ship confined to the channel (F91, S11).' },
      },
      // 11 ------------------------------------------------------------
      {
        id: 'small-craft',
        title: 'Small craft, kayaks and Rule 43 (part 4)',
        html: `<p>The smallest craft on the water are the hardest to see and the easiest to swamp. Norwegian Rule 43 therefore gives them one instruction: keep well out of everybody's way.</p>
<div class="callout rule"><p><strong>Norwegian Rule 43 (small vessels):</strong> a vessel under oars, and a power-driven or sailing vessel which carries only a white light under Rule 23 or 25, shall, when approaching other vessels or seeing them approach, <strong>manoeuvre with caution, slacken speed and if required stop</strong>; such vessels shall <strong>keep well out of the way</strong> of other vessels.</p></div>
<p>Who is covered: rowing boats, kayaks, canoes and similar craft under oars or paddles; a motorboat under 7 m with a top speed of 7 knots or less that shows only an all-round white light at night; a sailing boat under 7 m or a rowing boat that uses a white torch instead of sidelights. Rule 43 is a duty on the small craft, and it applies in any waters. Rule 44 then adds that open boats under oars, sail or engine keep clear of larger vessels, ferries and commercial traffic in narrow waters, busy fairways and harbours.</p>
<p>What about you in the motorboat meeting a kayak? COLREG gives neither of you formal priority: a kayak is a vessel (Rule 3(a)) but neither power-driven nor sailing, so Rule 18 is silent. Rules 2, 5, 6 and 8 are not silent: keep a good look-out, reduce speed, pass well clear and mind your wash, because a kayak cannot get out of your way quickly and your wake can capsize it. The exam framing is that paddled and rowed craft keep clear of other vessels, and that everybody is responsible for avoiding a collision.</p>
<p>Two further Norwegian rules in the curriculum. <strong>Rule 42:</strong> a vessel showing international code flag A (white and blue, swallow-tailed) has a diver down; pass with caution and, if power-driven, stop the engine if possible. <strong>Rule 54:</strong> the master of a decked Norwegian vessel must keep at least one copy of the Rules of the Road on board.</p>`,
        illustration: () => S.encounter('power-vs-rowing'),
        caption: 'Norwegian Rule 43: the rowing boat or kayak manoeuvres with caution, slows down and keeps well out of the way. The motorboat still keeps a look-out, slows down and passes well clear.',
        keyFacts: ['Rule 43: vessels under oars and small craft showing only a white light manoeuvre with caution, slacken speed, stop if required, keep WELL out of the way', 'A kayak is a vessel; Rule 18 gives it no rung; Rules 43 and 44 make it keep clear', 'The motorboat must still avoid collision: look-out, safe speed, pass well clear, mind the wash (Rules 2, 5, 6, 8)', 'Rule 42: flag A = diver down; pass with caution, stop the engine if possible', 'Rule 54: at least one copy of the Rules of the Road on board a decked Norwegian vessel'],
        check: { id: 'colregs-c11', q: 'Norwegian Rule 43 requires a kayak approaching other vessels to:', options: ['Hold course and speed as the stand-on vessel', 'Manoeuvre with caution, slacken speed, stop if required, and keep well out of the way', 'Sound five short blasts and continue', 'Show a red light to claim priority'], answer: 1, explanation: 'Rule 43 (small vessels): a vessel under oars, or a small craft carrying only a white light, manoeuvres with caution, slows down, stops if necessary and keeps well out of the way of other vessels (F90).' },
      },
      // 12 ------------------------------------------------------------
      {
        id: 'signals-and-fog',
        title: 'Sound signals, traffic lanes and fog',
        html: `<p>A turn is only useful to the other vessel if she can see it, and at close quarters a whistle says it faster. The curriculum requires Rule 34(a) and (b), Rule 35(a) and the small-craft exemption, and Rule 10 on traffic separation schemes.</p>
<p><strong>Manoeuvring signals, in sight (Rule 34):</strong> one short blast (about 1 s) means "I am altering my course to <strong>starboard</strong>"; two short blasts "to <strong>port</strong>"; three short blasts "I am operating <strong>astern</strong> propulsion". The same can be shown with one, two or three light flashes (34(b)). <strong>At least five short, rapid blasts</strong> mean "I do not understand your intentions" or "I doubt you are doing enough" (34(d)). One prolonged blast (4 to 6 s) when approaching a blind bend (34(e)).</p>
<p><strong>Restricted visibility (Rules 19 and 35):</strong> fog, mist, snow or heavy rain. Rule 19 applies to vessels <strong>not in sight of one another</strong>, so there is <strong>no stand-on vessel</strong>; every vessel goes at a safe speed with engines ready, and acts early. A vessel detecting another by radar alone should avoid altering to <strong>port</strong> for a vessel forward of the beam (unless overtaking her) and avoid turning <strong>towards</strong> a vessel abeam or abaft the beam. If you hear a fog signal forward of your beam, slow to bare steerage way or stop. Fog signals, every <strong>2 minutes at most</strong>: a power-driven vessel making way, <strong>one prolonged</strong> blast; underway but stopped, <strong>two prolonged</strong>; a sailing, fishing, NUC, RAM, constrained-by-draught or towing vessel, <strong>one prolonged and two short</strong>. A vessel under 12 m need not give these, but must then make some other efficient sound signal every 2 minutes.</p>
<p><strong>Traffic separation schemes (Rule 10):</strong> follow the lane in the direction of traffic flow, keep clear of the separation zone, join or leave at the ends. Avoid crossing; if you must, cross on a <strong>heading at right angles</strong> to the traffic flow. Vessels under 20 m and sailing vessels may use the inshore traffic zone and shall <strong>not impede</strong> a power-driven vessel following a lane.</p>`,
        illustration: () => signalCards(),
        caption: 'Sound signals you must know: 1, 2, 3 and at least 5 short blasts in sight; the narrow-channel overtaking signals; the fog signals; and the Norwegian long blast before a narrow channel.',
        keyFacts: ['1 short = altering to starboard; 2 short = to port; 3 short = astern propulsion; 5 or more short = doubt / danger', 'Short blast about 1 s; prolonged blast 4 to 6 s', 'Fog: no stand-on vessel; avoid altering to port for a vessel forward of the beam', 'Fog signals every 2 min: power making way 1 prolonged; stopped 2 prolonged; sail/fishing/NUC/RAM/towing 1 prolonged + 2 short', 'TSS: cross at right angles; under 20 m and sailing vessels do not impede vessels in a lane'],
        check: { id: 'colregs-c12', q: 'A motorboat near you sounds five short, rapid blasts. What does it mean?', options: ['She is altering course to starboard', 'She is going astern', 'She is in doubt about your intentions or whether you are doing enough to avoid collision', 'She is entering a narrow channel'], answer: 2, explanation: 'Rule 34(d): at least five short and rapid blasts is the doubt or danger signal. One short is starboard, three short is astern, and the Norwegian narrow-channel warning is one long blast of at least 10 s (F79, T14).' },
      },
    ],
    flashcards: [
      { front: 'Two power-driven vessels crossing: who gives way?', back: 'The vessel which has the other on her own STARBOARD side (Rule 15). She avoids crossing ahead.' },
      { front: 'Give-way vessel: how should she act?', back: 'Early and substantial action to keep well clear (Rule 16); typically turn to starboard and pass astern.' },
      { front: 'Stand-on vessel: what does she do?', back: 'Keeps course and speed (Rule 17). May act when the other clearly fails to; must act when the other alone can no longer avoid collision.' },
      { front: 'Stand-on vessel taking action: which turn to avoid?', back: 'Do not alter to PORT for a vessel on your own port side (Rule 17(c)).' },
      { front: 'Two power-driven vessels head-on?', back: 'BOTH alter course to starboard and pass port to port, red to red (Rule 14).' },
      { front: 'In doubt whether a situation is head-on?', back: 'Assume it is and alter to starboard (Rule 14(c)).' },
      { front: 'When are you "overtaking"?', back: 'Coming up from more than 22.5 degrees abaft the other\'s beam: her 135 degree sternlight sector (Rule 13(b)).' },
      { front: 'Who keeps clear when overtaking?', back: 'The overtaking vessel, whatever her type, on either side, until finally past and clear (Rule 13).' },
      { front: 'Sailing yacht overtaking a motorboat?', back: 'The yacht keeps clear: Rule 13 overrides Rule 18.' },
      { front: 'In doubt whether you are overtaking?', back: 'Assume you are and keep clear (Rule 13(c)).' },
      { front: 'Power-driven vessel vs sailing vessel, crossing?', back: 'The power-driven vessel keeps out of the way, whichever side the sailing vessel is on (Rule 18(a)(iv)).' },
      { front: 'Sails up, engine running: what kind of vessel?', back: 'Power-driven vessel (Rule 3(c)). Day signal: a cone, apex down (Rule 25(e)).' },
      { front: 'Definition of "sailing vessel"?', back: 'A vessel under sail provided that propelling machinery, if fitted, is not being used (Rule 3(c)).' },
      { front: 'Two sailing vessels, wind on different sides?', back: 'The one with the wind on her PORT side (port tack) gives way (Rule 12(a)(i)).' },
      { front: 'Two sailing vessels, wind on the same side?', back: 'The WINDWARD vessel (nearer the wind) gives way to the leeward vessel (Rule 12(a)(ii)).' },
      { front: 'Boom out to starboard: which tack?', back: 'Port tack (wind on the port side). Windward side = opposite the mainsail (Rule 12(b)).' },
      { front: 'Port-tack boat cannot tell the other\'s tack?', back: 'She keeps out of the way (Rule 12(a)(iii)).' },
      { front: 'Rule 18 ladder, top to bottom?', back: 'NUC and RAM, (constrained by draught: do not impede), fishing, sailing, power-driven. Seaplane/WIG keep clear of all.' },
      { front: 'Does a boat trolling a lure count as "engaged in fishing"?', back: 'No. Only gear that restricts manoeuvrability counts (Rule 3(d)); trolling lines do not.' },
      { front: 'Three all-round red lights in a vertical line?', back: 'Vessel constrained by her draught: avoid impeding her safe passage (Rules 28, 18(d)).' },
      { front: 'Sidelight arcs and colours?', back: 'Green starboard, red port, 112.5 degrees each, from right ahead to 22.5 degrees abaft the beam (Rule 21(b)).' },
      { front: 'Masthead and sternlight arcs?', back: 'Masthead white 225 degrees; sternlight white 135 degrees = the overtaking sector (Rule 21).' },
      { front: 'Red sidelight on your starboard bow at night?', back: 'A power-driven vessel crossing from your right: you give way (Rule 15).' },
      { front: 'Narrow channel: where do you keep?', back: 'As near the outer limit on your STARBOARD side as is safe (Rule 9(a)).' },
      { front: 'Rule 9(b): who must not impede a vessel confined to a narrow channel?', back: 'Vessels under 20 m and sailing vessels.' },
      { front: 'Norwegian Rule 44?', back: 'Pleasure craft and open boats under oars, sail or engine keep out of the way of larger vessels, scheduled ferries and commercial traffic in narrow waters, busy fairways and harbours.' },
      { front: 'Yacht under sail vs ferry in a narrow sound?', back: 'The yacht keeps clear (Norwegian Rule 44 and Rule 9(b)); sail has no priority here.' },
      { front: 'Norwegian Rule 43?', back: 'Vessels under oars and small craft showing only a white light: manoeuvre with caution, slacken speed, stop if required, keep WELL out of the way.' },
      { front: 'Norwegian Rule 41(a): entering a narrow channel?', back: 'Power-driven vessel sounds one long blast of at least 10 s from about half a nautical mile.' },
      { front: 'Norwegian Rule 45?', back: 'Do not anchor or make fast so as to impede or damage other vessels unless absolutely necessary.' },
      { front: 'Norwegian Rule 54?', back: 'The master of a decked Norwegian vessel keeps at least one copy of the Rules of the Road on board.' },
      { front: '1 / 2 / 3 short blasts?', back: 'Altering to starboard / altering to port / operating astern propulsion (Rule 34(a)).' },
      { front: 'At least five short rapid blasts?', back: 'Doubt or danger: "I do not understand your intentions" (Rule 34(d)).' },
      { front: 'Fog signal, power-driven vessel making way?', back: 'One prolonged blast (4 to 6 s) at intervals of not more than 2 minutes (Rule 35(a)).' },
      { front: 'Is there a stand-on vessel in fog?', back: 'No. Rule 19 applies to vessels not in sight of one another; every vessel acts. Avoid altering to port for a vessel forward of the beam.' },
      { front: 'Risk of collision test (Rule 7)?', back: 'Compass bearing not changing appreciably while the range decreases. If in doubt, assume risk exists.' },
      { front: 'Crossing a traffic separation scheme?', back: 'Avoid if possible; otherwise cross on a heading at right angles to the traffic flow (Rule 10(c)).' },
    ],
    questions: [
      // ---- Part 4, 1.4.3: two motorboats on crossing courses ----
      { id: 'colregs-01', q: 'Look at the picture. Two motorboats are on crossing courses and the bearing of A is steady. Who must keep out of the way?', options: ['You, because A is on your starboard side', 'A, because she is on the starboard side', 'The faster of the two boats', 'Neither: both alter course to starboard'], answer: 0, explanation: 'Rule 15: the power-driven vessel which has the other on her own starboard side keeps out of the way. A is on your starboard bow, so you give way, turning to starboard to pass astern of her (F56, S1).', illustration: qCrossStbd, difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-15', 'crossing'] },
      { id: 'colregs-02', q: 'Look at the picture. Motorboat B is on your port bow on a steady bearing. What should you do?', options: ['Give way by altering course to port and passing astern of B', 'Give way by stopping; the boat on the right always stops', 'Keep course and speed; B must keep out of your way', 'Alter course to starboard; both vessels must turn to starboard'], answer: 2, explanation: 'B has you on her starboard side, so B is the give-way vessel and you are stand-on: keep course and speed and watch her (Rules 15 and 17). Only if she clearly does nothing do you act, and then not by turning to port (S2).', illustration: qCrossPort, difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-15', 'rule-17', 'crossing'] },
      { id: 'colregs-03', q: 'Two motorboats are on crossing courses with risk of collision. Which one must keep out of the way?', options: ['The boat that has the other on her own starboard side', 'The boat that has the other on her own port side', 'The larger boat', 'The faster boat'], answer: 0, explanation: 'Rule 15: in a crossing between two power-driven vessels the one which has the other on her starboard side gives way and avoids crossing ahead. Size and speed are irrelevant (F56).', difficulty: 1, part: 4, p4: '1.4.3', tags: ['rule-15', 'crossing'] },
      { id: 'colregs-04', q: 'You are the give-way motorboat in a crossing situation. Which action is correct?', options: ['A small course change to port to pass ahead of her', 'A series of small alterations so as not to alarm her', 'Hold course and speed and sound one short blast', 'An early, substantial turn to starboard to pass astern of her, or slow down'], answer: 3, explanation: 'Rules 15 and 16: the give-way vessel takes early and substantial action to keep well clear and avoids crossing ahead; turning to starboard and passing astern is the standard move. Rule 8 forbids a succession of small alterations (F56, F58, F27).', difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-16', 'crossing'] },
      { id: 'colregs-05', q: 'At night you see these lights on your starboard bow. The bearing is steady and the range is decreasing. What is the situation?', options: ['A sailing vessel: she must give way to you', 'A power-driven vessel crossing from your right: you must keep out of her way', 'A power-driven vessel crossing from your left: you stand on', 'A vessel at anchor: pass on either side'], answer: 1, explanation: 'A white masthead light over a red sidelight is a power-driven vessel showing you her port side; she is heading across your bow from starboard. Rule 15: you give way. Memory aid: red on your starboard bow means stop (F57).', illustration: qNightPort, difficulty: 3, part: 4, p4: '1.4.3', tags: ['rule-15', 'lights', 'night'] },
      { id: 'colregs-06', q: 'At night you see a white masthead light over a green sidelight on your port bow, on a steady bearing. What do you do?', options: ['Alter course to port to pass ahead of her', 'Alter course to starboard; both vessels must turn to starboard', 'Keep course and speed; she has you on her starboard side and must give way', 'Stop and wait, because green means she has priority'], answer: 2, explanation: 'Her green sidelight on your port bow means a power-driven vessel crossing from your left; she has you on her starboard side and gives way (Rule 15). You stand on under Rule 17, ready to act if she does not (F57, S2).', illustration: qNightStarboard, difficulty: 3, part: 4, p4: '1.4.3', tags: ['rule-15', 'lights', 'night'] },
      { id: 'colregs-07', q: 'You are the stand-on motorboat. The give-way motorboat on your port side is 200 m away and clearly not reacting. What is the correct response?', options: ['Keep course and speed whatever happens; the stand-on vessel may never alter', 'Turn to port towards her so that you pass starboard to starboard', 'Sound one short blast and speed up to pass ahead of her', 'Act now: slow down or turn to starboard, sound at least five short blasts; avoid turning to port'], answer: 3, explanation: 'Rule 17(a)(ii) lets the stand-on vessel act as soon as it is apparent the other is not acting, and 17(b) obliges her to when collision can no longer be avoided by the other alone. Rule 17(c): do not turn to port for a vessel on your port side (F60 to F62, S17).', difficulty: 3, part: 4, p4: '1.4.3', tags: ['rule-17', 'crossing'] },
      { id: 'colregs-08', q: 'In a crossing situation between two motorboats, what does the stand-on vessel do while the other gives way?', options: ['Keeps her course and speed', 'Stops her engine', 'Alters course to port to make room', 'Alters course to starboard to make room'], answer: 0, explanation: 'Rule 17(a)(i): the stand-on vessel keeps her course and speed so that the give-way vessel can manoeuvre around a predictable target (F59).', difficulty: 1, part: 4, p4: '1.4.3', tags: ['rule-17', 'crossing'] },
      // ---- Part 4, 1.4.3: motorboat and sailing vessel on crossing courses ----
      { id: 'colregs-09', q: 'Look at the picture. You are the motorboat; D is a yacht under sail with her engine off, crossing from your port side. Who gives way?', options: ['D, because you are on her starboard side', 'Neither; both alter course to starboard', 'You, because a power-driven vessel keeps out of the way of a sailing vessel', 'D, because the vessel on the left always gives way'], answer: 2, explanation: 'Rule 18(a)(iv): a power-driven vessel keeps out of the way of a sailing vessel whichever side she is on. The starboard-side rule of Rule 15 only applies between two power-driven vessels (F65, S4).', illustration: qPowerSail, difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-18', 'sail'] },
      { id: 'colregs-10', q: 'Look at the picture. E has her sails up but her engine is running (black cone, apex down). She is crossing from your port side on a steady bearing. Who gives way?', options: ['You, because she has sails up', 'Neither; both alter course to starboard', 'You, because the cone means she is restricted in her ability to manoeuvre', 'E: with her engine in use she is a power-driven vessel and has you on her starboard side'], answer: 3, explanation: 'Rule 3(c): a vessel under sail with her engine in use is a power-driven vessel; the cone apex down is her day signal (Rule 25(e)). Two power-driven vessels crossing: E has you on her starboard side, so E gives way (Rule 15) (F8, F9, S5).', illustration: qSailMotor, difficulty: 3, part: 4, p4: '1.4.3', tags: ['rule-3', 'rule-15', 'cone'] },
      { id: 'colregs-11', q: 'A sailing yacht has her sails up and her engine running. In the Rules of the Road she is a:', options: ['Sailing vessel', 'Vessel restricted in her ability to manoeuvre', 'Vessel not under command', 'Power-driven vessel'], answer: 3, explanation: 'Rule 3(c): a vessel is a sailing vessel only when any propelling machinery is not being used. With the engine on she is power-driven and the motorboat rules apply to her (F8).', difficulty: 1, part: 4, p4: '1.4.3', tags: ['rule-3', 'sail'] },
      { id: 'colregs-12', q: 'Look at the picture. You are the motorboat; F is a yacht under sail, engine off, crossing from your starboard side. Who gives way?', options: ['You: the motorboat gives way to the sailing vessel, and she is on your starboard side anyway', 'F, because sailing vessels always give way in open water', 'F, because you are on her port side', 'Neither; you pass starboard to starboard'], answer: 0, explanation: 'Rule 18(a)(iv): the power-driven vessel keeps out of the way of a sailing vessel on either side. Here even the Rule 15 logic points the same way, since F is on your starboard side (F65).', illustration: qPowerSailStbd, difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-18', 'sail'] },
      { id: 'colregs-13', q: 'Look at the picture. Sailing yacht K is faster and is coming up on motorboat J from more than 22.5 degrees abaft J\'s beam. Who keeps clear?', options: ['J, because a power-driven vessel gives way to a sailing vessel', 'J, because K is on her starboard quarter', 'K, because an overtaking vessel keeps clear whatever her type', 'Neither; both alter course to starboard'], answer: 2, explanation: 'Rule 13(a) applies notwithstanding Rule 18: any vessel overtaking any other keeps out of the way. The overtaking yacht gives way to the motorboat she is overtaking (F49, S8).', illustration: qSailOvertake, difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-13', 'sail'] },
      { id: 'colregs-14', q: 'You are in a motorboat and must give way to a yacht under sail crossing ahead of you. What is the best way to do it?', options: ['Pass close ahead of her bow so that she need not change course', 'Keep course and speed until she tacks', 'Alter course only slightly so she does not notice', 'Alter course early and substantially and pass well clear, preferably astern of her'], answer: 3, explanation: 'Rules 16 and 8: early, substantial action that is obvious to the other vessel; pass astern and leave room because a yacht may tack or gybe and swing through a wide angle (F58, S4).', difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-16', 'rule-18', 'sail'] },
      { id: 'colregs-15', q: 'In open water, which vessel must keep out of the way of a sailing vessel under sail on a crossing course?', options: ['A power-driven vessel', 'A vessel engaged in fishing', 'A vessel not under command', 'A vessel restricted in her ability to manoeuvre'], answer: 0, explanation: 'Rule 18(a)(iv): a power-driven vessel keeps out of the way of a sailing vessel. The sailing vessel herself keeps out of the way of fishing, NUC and RAM vessels (Rule 18(b)) (F65, F66).', difficulty: 1, part: 4, p4: '1.4.3', tags: ['rule-18', 'sail'] },
      { id: 'colregs-16', q: 'A motorboat trolling a single fishing lure astern meets a yacht under sail on a crossing course in open water. Who gives way?', options: ['The yacht: a vessel engaged in fishing has priority', 'The yacht: the motorboat is on her starboard side', 'The motorboat: trolling does not make her "engaged in fishing", so she is an ordinary power-driven vessel', 'Neither; both alter to starboard'], answer: 2, explanation: 'Rule 3(d) excludes trolling lines and other gear that does not restrict manoeuvrability. The motorboat is simply power-driven and gives way to the sailing vessel under Rule 18(a)(iv) (F10, T11).', difficulty: 3, part: 4, p4: '1.4.3', tags: ['rule-3', 'rule-18', 'fishing'] },
      // ---- Part 4, 1.4.3: small craft vs ferry / cargo ship in narrow waters ----
      { id: 'colregs-17', q: 'Look at the picture. In a narrow sound a scheduled ferry is coming towards you on your port bow; you are in a 6 m motorboat. Who keeps out of the way?', options: ['The ferry, because you are on her starboard side (Rule 15)', 'You: pleasure craft keep out of the way of scheduled ferries in narrow waters (Norwegian Rule 44)', 'Both alter course to starboard (Rule 14)', 'The ferry, because the larger vessel always gives way to the smaller'], answer: 1, explanation: 'Norwegian Rule 44: pleasure craft under oars, sail or engine keep out of the way of larger vessels, scheduled ferries and other commercial traffic in narrow waters, busy fairways and harbour areas. Slow down early, keep to your starboard side, pass astern or wait (F91, S11).', illustration: qFerryMotor, difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-44', 'ferry', 'narrow-channel'] },
      { id: 'colregs-18', q: 'Look at the picture. You are a 9 m yacht under sail, engine off, meeting a coastal cargo ship in a narrow sound where she can only navigate inside the channel. Who keeps clear?', options: ['The cargo ship, because a power-driven vessel gives way to a sailing vessel', 'Both alter course to starboard', 'The cargo ship, because she is on your port side', 'You: a sailing vessel must not impede a ship confined to the channel (Rule 9(b)), and Norwegian Rule 44 applies to craft under sail too'], answer: 3, explanation: 'Rule 18 opens with "except where Rules 9, 10 and 13 otherwise require". Rule 9(b) forbids a sailing vessel from impeding a vessel that can only navigate within a narrow channel, and Norwegian Rule 44 covers pleasure craft under oars, sail or engine. Sail has no priority here (F33, F92, S11).', illustration: qFerrySail, difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-44', 'rule-9', 'sail', 'narrow-channel'] },
      { id: 'colregs-19', q: 'In a Norwegian harbour a yacht under sail is on a collision course with a coastal cargo ship. Who should keep clear?', options: ['The yacht, under Norwegian Rule 44 and Rule 9(b)', 'The cargo ship, because power gives way to sail', 'The yacht, but only if she is on port tack', 'Neither; both alter to starboard'], answer: 0, explanation: 'Norwegian Rule 44 applies in narrow waters, heavily trafficked fairways and harbour areas to pleasure craft under oars, sail or engine, and Rule 9(b) says a sailing vessel shall not impede a ship confined to the channel (F92).', difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-44', 'sail', 'harbour'] },
      { id: 'colregs-20', q: 'A small motorboat and a scheduled ferry approach each other in a narrow Norwegian sound. Which rule tells the motorboat what to do?', options: ['Rule 14: both alter course to starboard', 'Rule 18: the ferry gives way to the smaller craft', 'Norwegian Rule 44: pleasure craft keep out of the way of larger vessels, scheduled ferries and commercial traffic in narrow waters, busy fairways and harbours', 'Norwegian Rule 45: the ferry must anchor and wait'], answer: 2, explanation: 'Norwegian Chapter II, Rule 44 (F91). Rule 45 is about not anchoring so as to impede others; Rule 14 is for head-on between two power-driven vessels in general, and Rule 18 does not give small craft priority over ferries.', difficulty: 1, part: 4, p4: '1.4.3', tags: ['rule-44', 'ferry'] },
      { id: 'colregs-21', q: 'You meet a scheduled ferry in a narrow sound. Which action is correct?', options: ['Cross close ahead of her so you are out of her way sooner', 'Keep to the middle of the channel so she can see you', 'Hold course and speed because you are the stand-on vessel', 'Slow down early, keep to your own starboard side of the channel, and pass astern of her or wait'], answer: 3, explanation: 'Rule 9(a) (keep to the starboard outer limit) plus Norwegian Rule 44 (keep out of the way of ferries in narrow waters). Never cross close ahead of a ferry (S11).', difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-44', 'rule-9', 'ferry'] },
      { id: 'colregs-22', q: 'Rule 9(b): which vessels shall not impede the passage of a vessel that can safely navigate only within a narrow channel?', options: ['Vessels of less than 20 m in length and sailing vessels', 'Only sailing vessels', 'Only vessels of less than 7 m', 'Only fishing vessels'], answer: 0, explanation: 'Rule 9(b) names vessels under 20 m and sailing vessels. Fishing vessels are covered separately by Rule 9(c) (F33, F34).', difficulty: 1, part: 4, p4: '1.4.3', tags: ['rule-9', 'narrow-channel'] },
      { id: 'colregs-23', q: 'In a harbour area a car ferry is leaving her berth and swinging out into the fairway as you approach in a 7 m motorboat with the ferry on your port side. What do you do?', options: ['Hold course and speed; she is on your port side so she must give way', 'Keep well clear and give her room to swing; pleasure craft keep out of the way of ferries in harbour areas (Norwegian Rule 44)', 'Sound five short blasts and pass close ahead of her bow', 'Alter course to port to pass between the ferry and the quay'], answer: 1, explanation: 'Norwegian Rule 44 applies in harbour areas as well as narrow waters and busy fairways: the pleasure craft keeps out of the way of scheduled ferries and commercial traffic. Never cross close ahead of a ferry leaving a berth (F91, S11).', difficulty: 3, part: 4, p4: '1.4.3', tags: ['rule-44', 'ferry', 'harbour'] },
      // ---- Part 4, 1.4.3: Norwegian Rules 43 and 44 ----
      { id: 'colregs-24', q: 'Norwegian Rule 43 requires a rowing boat, or a small craft showing only a white light, that is approaching other vessels to:', options: ['Hold course and speed as the stand-on vessel', 'Sound five short blasts', 'Manoeuvre with caution, slacken speed, stop if required, and keep well out of the way', 'Show a red light to warn the other vessel'], answer: 2, explanation: 'Norwegian Rule 43 (small vessels): such vessels manoeuvre with caution, slacken speed and if required stop, and keep well out of the way of other vessels (F90).', difficulty: 1, part: 4, p4: '1.4.3', tags: ['rule-43'] },
      { id: 'colregs-25', q: 'Which vessels does Norwegian Rule 43 apply to?', options: ['Vessels under oars, and power-driven or sailing vessels that carry only a white light', 'All vessels under 20 m', 'Scheduled ferries in narrow waters', 'Only vessels engaged in fishing'], answer: 0, explanation: 'Rule 43 covers vessels under oars (rowing boats, kayaks, canoes) and the small power-driven or sailing craft that under Rules 23 and 25 carry only a white light (F90).', difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-43'] },
      { id: 'colregs-26', q: 'What does Norwegian Rule 44 say?', options: ['Larger vessels keep out of the way of pleasure craft in narrow waters', 'Pleasure craft and open boats under oars, sail or engine shall as far as practicable keep out of the way of larger vessels, scheduled ferries and other commercial traffic in narrow waters, busy fairways and harbour areas', 'A power-driven vessel entering a narrow channel sounds one long blast of at least 10 seconds', 'Every vessel shall keep a copy of the Rules of the Road on board'], answer: 1, explanation: 'That is Rule 44 (F91). The long blast is Rule 41(a) and the copy of the rules is Rule 54.', difficulty: 1, part: 4, p4: '1.4.3', tags: ['rule-44'] },
      { id: 'colregs-27', q: 'Where does Norwegian Rule 44 apply?', options: ['Only in traffic separation schemes', 'Only in restricted visibility', 'Everywhere at sea, including the open coast', 'In narrow waters, heavily trafficked fairways and harbour areas'], answer: 3, explanation: 'Rule 44 is written for confined and busy waters: narrow waters, heavily trafficked fairways and harbour areas (F91). In open water with sea room the ordinary rules apply, though keeping clear of big ships is still good seamanship (T16).', difficulty: 1, part: 4, p4: '1.4.3', tags: ['rule-44'] },
      { id: 'colregs-28', q: 'Does Norwegian Rule 44 apply to a yacht under sail with her engine off?', options: ['No; a sailing vessel always has priority over power-driven vessels', 'Only when the yacht is on port tack', 'Only at night', 'Yes; it covers pleasure craft under oars, sail or engine'], answer: 3, explanation: 'Rule 44 names pleasure craft and open boats "under oars, sail or engine". In a narrow sound or harbour a yacht under sail keeps clear of ferries and commercial traffic (F92).', difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-44', 'sail'] },
      { id: 'colregs-29', q: 'Look at the picture. A kayak is paddling towards you along the shore of a narrow sound. What does Norwegian Rule 43 require of the kayak?', options: ['Keep course and speed; she is the stand-on vessel', 'Sound one short blast and turn to starboard', 'Manoeuvre with caution, slow down, stop if necessary and keep well out of your way', 'Nothing; a kayak is not a vessel under the rules'], answer: 2, explanation: 'A kayak is a vessel (Rule 3(a)) and is a vessel under oars or paddles; Norwegian Rule 43 requires it to manoeuvre with caution, slacken speed, stop if required and keep well out of the way (F6, F90, S12).', illustration: qKayak, difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-43', 'kayak'] },
      { id: 'colregs-30', q: 'You are in a motorboat meeting a kayak in a narrow sound. What must YOU do?', options: ['Nothing; Rule 43 puts the whole duty on the kayak', 'Hold course and speed as the stand-on vessel', 'Keep a good look-out, reduce speed and pass well clear, minding your wash (Rules 2, 5, 6 and 8)', 'Sound five short blasts and continue at the same speed'], answer: 2, explanation: 'COLREG gives neither vessel formal priority, but Rules 2, 5, 6 and 8 still bind the motorboat: look-out, safe speed, early action and a safe passing distance. A kayak cannot get out of your way quickly and your wash can capsize it (F71, S12).', difficulty: 3, part: 4, p4: '1.4.3', tags: ['rule-43', 'kayak', 'rule-2'] },
      { id: 'colregs-31', q: 'At night a 5 m motorboat showing only a single all-round white light sees a larger vessel approaching. What does Norwegian Rule 43 require of the small boat?', options: ['Switch on sidelights and claim the stand-on role', 'Manoeuvre with caution, slacken speed, stop if required and keep well out of the way', 'Sound one prolonged blast every two minutes', 'Hold course and speed'], answer: 1, explanation: 'Rule 43 applies to a power-driven or sailing vessel that carries only a white light under Rule 23 or 25, as well as to vessels under oars: caution, reduced speed, stop if needed, keep well clear (F90, F84).', difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-43', 'lights'] },
      { id: 'colregs-32', q: 'A small open motorboat is crossing a heavily trafficked fairway when a coastal cargo ship approaches along it. Under Norwegian Rule 44 the motorboat should:', options: ['Keep out of the way of the cargo ship as far as practicable', 'Hold course, because a vessel crossing a fairway has priority over traffic along it', 'Expect the cargo ship to give way if the motorboat is on her starboard side', 'Anchor in the fairway until the ship has passed'], answer: 0, explanation: 'Rule 44: pleasure craft and open boats keep out of the way of larger vessels and commercial traffic in narrow waters, heavily trafficked fairways and harbours. Rule 9(d) also says do not cross a channel so as to impede a vessel confined to it, and Rule 45 forbids anchoring where you impede others (F91, F35, F93).', difficulty: 2, part: 4, p4: '1.4.3', tags: ['rule-44', 'fairway'] },
      // ---- Part 2: head-on ----
      { id: 'colregs-33', q: 'Look at the picture. Two motorboats meet on reciprocal courses with risk of collision. What should they do?', options: ['Both alter course to port', 'The smaller boat alters to starboard, the other holds her course', 'Both stop and wait', 'Both alter course to starboard and pass port to port'], answer: 3, explanation: 'Rule 14: when two power-driven vessels meet head-on, each alters course to starboard so that they pass on each other\'s port side, red to red (F53).', illustration: qHeadOn, difficulty: 1, part: 2, tags: ['rule-14', 'head-on'] },
      { id: 'colregs-34', q: 'At night you see both the red and the green sidelight of a vessel ahead with her masthead lights in a line. What situation is this, and what do you do?', options: ['Crossing; keep course and speed', 'Head-on; alter course to starboard', 'Overtaking; pass on either side', 'Head-on; alter course to port'], answer: 1, explanation: 'Rule 14(b): seeing both sidelights and the masthead lights in line means head-on. Each power-driven vessel alters to starboard (F54, S3).', difficulty: 2, part: 2, tags: ['rule-14', 'night'] },
      { id: 'colregs-35', q: 'Two yachts under sail meet exactly bow to bow. Which rule decides who gives way?', options: ['Rule 14: both alter course to starboard', 'Rule 12: the tack rules decide, port tack gives way to starboard tack', 'Rule 13: the faster yacht keeps clear', 'Rule 18: the smaller yacht gives way'], answer: 1, explanation: 'Rule 14 applies only between two power-driven vessels. Two sailing vessels, head-on or otherwise, are governed by Rule 12: wind on different sides, port tack gives way (F55, T20).', difficulty: 3, part: 2, tags: ['rule-12', 'rule-14', 'sail'] },
      // ---- Part 2: overtaking ----
      { id: 'colregs-36', q: 'Look at the picture. Motorboat G is faster and is coming up on motorboat H from astern. Who keeps clear?', options: ['H, because G is on her starboard quarter', 'Neither; both alter course to starboard', 'G, the overtaking vessel, until she is finally past and clear', 'H, because the slower vessel must make room'], answer: 2, explanation: 'Rule 13: a vessel coming up from more than 22.5 degrees abaft the other\'s beam is overtaking and keeps out of the way, on either side, until finally past and clear (F50, F52, S8).', illustration: qOvertake, difficulty: 2, part: 2, tags: ['rule-13', 'overtaking'] },
      { id: 'colregs-37', q: 'From what direction must you approach another vessel to be "overtaking" her?', options: ['From anywhere abaft her beam', 'From more than 22.5 degrees abaft her beam, within her 135 degree sternlight sector', 'From her starboard side only', 'From within 45 degrees of dead astern'], answer: 1, explanation: 'Rule 13(b): overtaking means coming up from a direction more than 22.5 degrees abaft the beam, the 135 degree sector in which at night only the sternlight is visible. "Anywhere abaft the beam" would be 180 degrees, which is wrong (F50, T7).', difficulty: 1, part: 2, tags: ['rule-13', 'overtaking'] },
      { id: 'colregs-38', q: 'At night you see only a single white light of a vessel ahead and you are gaining on her. What is your status?', options: ['Overtaking vessel: keep clear until finally past and clear', 'Stand-on vessel: keep course and speed', 'Head-on: alter course to starboard', 'She is at anchor: no action needed'], answer: 0, explanation: 'Seeing only the sternlight means you are inside her 135 degree overtaking sector (Rule 13(b)); you keep out of her way until finally past and clear (Rule 13(d)) (F50, F52).', difficulty: 2, part: 2, tags: ['rule-13', 'night'] },
      { id: 'colregs-39', q: 'You are overtaking a motorboat. As you draw level the bearing between you changes so that she is now abeam. Which statement is correct?', options: ['It is now a crossing situation and she must give way to you', 'You remain the overtaking vessel and keep clear until finally past and clear', 'Both of you must now alter course to starboard', 'You may now cross ahead of her'], answer: 1, explanation: 'Rule 13(d): a later change of bearing does not make the overtaking vessel a crossing vessel, nor relieve her of the duty to keep clear until finally past and clear (F52, T8).', difficulty: 3, part: 2, tags: ['rule-13', 'overtaking'] },
      // ---- Part 2: sail vs sail ----
      { id: 'colregs-40', q: 'Look at the picture. Two yachts under sail converge with the wind from the north. L has her boom out to starboard, M has her boom out to port. Who gives way?', options: ['M, because she is on L\'s starboard side', 'The yacht to leeward', 'L: boom to starboard means wind on her port side, so she is on port tack', 'Neither; both alter course to starboard'], answer: 2, explanation: 'Rule 12(a)(i): with the wind on different sides, the vessel with the wind on her port side keeps out of the way. Rule 12(b): the windward side is opposite the mainsail, so boom to starboard means port tack (F45, F48, S6).', illustration: qSailOpp, difficulty: 2, part: 2, tags: ['rule-12', 'sail'] },
      { id: 'colregs-41', q: 'Look at the picture. Both yachts have the wind on the same side; N is nearer to where the wind comes from. Who gives way?', options: ['N, the windward yacht', 'P, the leeward yacht', 'The yacht with the larger sail area', 'The yacht that is astern'], answer: 0, explanation: 'Rule 12(a)(ii): when both have the wind on the same side, the vessel to windward keeps out of the way of the vessel to leeward (F46, S7).', illustration: qSailSame, difficulty: 2, part: 2, tags: ['rule-12', 'sail'] },
      { id: 'colregs-42', q: 'A yacht\'s boom is out to starboard. On which tack is she?', options: ['Starboard tack', 'She is running, so she has no tack', 'It cannot be determined from the boom', 'Port tack'], answer: 3, explanation: 'Rule 12(b): the windward side is the side opposite to that on which the mainsail is carried. Boom to starboard means the wind comes over the port side: port tack (F48, T5).', difficulty: 1, part: 2, tags: ['rule-12', 'sail'] },
      { id: 'colregs-43', q: 'You are sailing on port tack and see a yacht to windward, but cannot tell with certainty which tack she is on. What does Rule 12 say?', options: ['Hold your course; the windward yacht always gives way', 'Keep out of her way', 'Sound five short blasts and wait for her to act', 'Both alter course to starboard'], answer: 1, explanation: 'Rule 12(a)(iii): a vessel with the wind on her port side which sees a vessel to windward and cannot determine her tack shall keep out of the way (F47).', difficulty: 3, part: 2, tags: ['rule-12', 'sail'] },
      // ---- Part 2: hierarchy ----
      { id: 'colregs-44', q: 'Rank from highest to lowest priority: (1) sailing vessel, (2) vessel engaged in fishing, (3) power-driven vessel, (4) vessel not under command.', options: ['4, 2, 1, 3', '2, 4, 1, 3', '4, 1, 2, 3', '3, 1, 2, 4'], answer: 0, explanation: 'Rule 18: not under command at the top, then fishing, then sailing, then power-driven at the bottom (F70).', difficulty: 2, part: 2, tags: ['rule-18'] },
      { id: 'colregs-45', q: 'By day a vessel shows two cones, apex to apex, in a vertical line. A motorboat and a yacht under sail are both on crossing courses with her. Who keeps clear?', options: ['Only the motorboat; the yacht has priority over fishing vessels', 'Only the yacht; the motorboat has priority', 'Both the motorboat and the yacht keep out of her way', 'The fishing vessel keeps clear of both'], answer: 2, explanation: 'Two cones apex to apex is a vessel engaged in fishing. Rule 18(a)(iii) and (b)(iii): both power-driven and sailing vessels keep out of her way, and of her gear (F65, F66, S10).', difficulty: 2, part: 2, tags: ['rule-18', 'fishing'] },
      { id: 'colregs-46', q: 'A ship shows three all-round red lights in a vertical line. What is she, and what do you do?', options: ['Constrained by her draught; avoid impeding her safe passage', 'Not under command; everyone keeps clear', 'Engaged in fishing; keep clear of her gear', 'Aground; pass well clear of the shallows'], answer: 0, explanation: 'Three all-round red lights (a cylinder by day) is the Rule 28 signal of a vessel constrained by her draught. Rule 18(d): avoid impeding her safe passage; do not cross ahead (F68, S13).', difficulty: 2, part: 2, tags: ['rule-18', 'rule-28', 'cbd'] },
      { id: 'colregs-47', q: 'Which vessel does a sailing vessel underway have to keep out of the way of under Rule 18(b)?', options: ['A power-driven vessel', 'A vessel engaged in fishing', 'A seaplane on the water', 'A scheduled ferry in open water'], answer: 1, explanation: 'Rule 18(b): a sailing vessel keeps out of the way of vessels not under command, vessels restricted in their ability to manoeuvre, and vessels engaged in fishing. Power-driven vessels give way to her (F66).', difficulty: 1, part: 2, tags: ['rule-18', 'sail'] },
      // ---- Part 2: look-out, safe speed, risk, action ----
      { id: 'colregs-48', q: 'Look at the picture. In three snapshots the other boat stays on the same compass bearing from you while the distance shrinks. What does Rule 7 say?', options: ['No risk of collision, because she is not pointing at you', 'Risk of collision exists only if she is on your starboard side', 'Risk of collision shall be deemed to exist', 'Risk of collision exists only in restricted visibility'], answer: 2, explanation: 'Rule 7(d)(i): if the compass bearing of an approaching vessel does not appreciably change while the range decreases, risk of collision shall be deemed to exist. Rule 7(a): if in doubt, assume it exists (F23, F24).', illustration: () => bearingSnapshots(), difficulty: 2, part: 2, tags: ['rule-7', 'bearing'] },
      { id: 'colregs-49', q: 'Rule 8 says that action to avoid collision should be:', options: ['A series of small course changes so as not to alarm the other vessel', 'Delayed until it is certain that the other vessel will not act', 'Always a reduction of speed, never an alteration of course', 'Positive, made in ample time, and large enough to be readily apparent to the other vessel'], answer: 3, explanation: 'Rule 8(a) and (b): action shall be positive, early and substantial enough to be readily apparent visually or by radar; a succession of small alterations is to be avoided (F27).', difficulty: 2, part: 2, tags: ['rule-8'] },
      { id: 'colregs-50', q: 'Which of these is NOT one of the factors Rule 6 lists for determining a safe speed?', options: ['The state of visibility', 'Background shore lights at night', 'Your draught in relation to the available depth', 'The posted local speed limit'], answer: 3, explanation: 'Rule 6(a) lists visibility, traffic density, manoeuvrability and stopping distance, background light at night, wind, sea, current and hazards, and draught versus depth. A posted limit is a separate local regulation; safe speed may be far below it (F21, T13).', difficulty: 2, part: 2, tags: ['rule-6', 'safe-speed'] },
      // ---- Part 2: narrow channels, Norwegian rules ----
      { id: 'colregs-51', q: 'In a narrow channel or fairway a vessel shall keep:', options: ['In the middle of the channel', 'As near to the outer limit on her port side as is safe', 'Wherever the water is deepest', 'As near to the outer limit on her starboard side as is safe and practicable'], answer: 3, explanation: 'Rule 9(a): keep as near to the outer limit of the channel which lies on your starboard side as is safe and practicable, in other words drive on the right (F32).', difficulty: 1, part: 2, tags: ['rule-9', 'narrow-channel'] },
      { id: 'colregs-52', q: 'Under Norwegian Rule 41, a power-driven vessel approaching a narrow channel shall:', options: ['Sound one short blast at the entrance', 'Sound two prolonged blasts every two minutes', 'Sound one long blast of at least 10 seconds from about half a nautical mile', 'Stop and wait in all cases'], answer: 2, explanation: 'Norwegian Rule 41(a): warn of your arrival from about half a mile with a long blast of at least 10 seconds. If two vessels cannot pass, the one arriving last waits (41(b)) (F86, T15).', difficulty: 2, part: 2, tags: ['rule-41', 'narrow-channel'] },
      { id: 'colregs-53', q: 'A scheduled ferry and your motorboat are on crossing courses in open water with plenty of sea room; the ferry is on your port side with a steady bearing. Which statement is correct?', options: ['Norwegian Rule 44 applies everywhere, so you must give way', 'Rule 15 applies: the ferry has you on her starboard side and is the give-way vessel; you stand on, but watch her closely and act if she does not', 'Rule 14 applies: both alter course to starboard', 'The ferry always has priority because she is bigger'], answer: 1, explanation: 'Rule 44 is limited to narrow waters, heavily trafficked fairways and harbour areas. In open water the ordinary rules apply: Rule 15 between two power-driven vessels. As stand-on you still keep a close watch and act under Rule 17 if she does not (T16, F91).', difficulty: 3, part: 2, tags: ['rule-44', 'rule-15', 'ferry'] },
      { id: 'colregs-54', q: 'What does Norwegian Rule 45 say about anchoring?', options: ['Anchoring is forbidden everywhere in Norwegian inland waters', 'Vessels shall not, unless absolutely necessary, anchor or make fast so as to impede the passage of, or damage, other vessels', 'Vessels may anchor anywhere if they show an anchor light', 'Only scheduled ferries may anchor in a fairway'], answer: 1, explanation: 'Norwegian Rule 45: do not anchor or make fast so as to impede or damage other vessels unless absolutely necessary. Rule 9(g) likewise says avoid anchoring in a narrow channel (F93, F39).', difficulty: 2, part: 2, tags: ['rule-45'] },
      { id: 'colregs-55', q: 'What does Norwegian Rule 54 require?', options: ['The master of a decked Norwegian vessel keeps at least one copy of the Rules of the Road on board', 'Every vessel carries a VHF radio', 'Pleasure craft keep clear of ferries in narrow waters', 'Every vessel sounds a long blast before entering a harbour'], answer: 0, explanation: 'Norwegian Rule 54: at least one copy of the Rules of the Road must be kept on board every decked Norwegian vessel (F94). Keeping clear of ferries is Rule 44.', difficulty: 1, part: 2, tags: ['rule-54'] },
      // ---- Part 2: sound signals, fog, TSS, responsibility ----
      { id: 'colregs-56', q: 'One short blast on the whistle means:', options: ['I am altering my course to port', 'I am operating astern propulsion', 'I am altering my course to starboard', 'I am in doubt about your intentions'], answer: 2, explanation: 'Rule 34(a): one short blast = altering to starboard, two short = altering to port, three short = astern propulsion; at least five short rapid blasts = doubt (F77, F79).', difficulty: 1, part: 2, tags: ['rule-34', 'sound'] },
      { id: 'colregs-57', q: 'In fog you detect by radar alone a vessel forward of your beam, closing. Which course alteration should you avoid?', options: ['An alteration to port, unless you are overtaking her', 'An alteration to starboard', 'Any alteration of course; you must only reduce speed', 'An alteration away from her'], answer: 0, explanation: 'Rule 19(d)(i): avoid an alteration to port for a vessel forward of the beam, other than one being overtaken. Rule 19(d)(ii): avoid turning towards a vessel abeam or abaft the beam (F74, S15).', difficulty: 3, part: 2, tags: ['rule-19', 'fog'] },
      { id: 'colregs-58', q: 'Which statement about restricted visibility (fog) is correct?', options: ['The vessel on the starboard side is the stand-on vessel', 'Rules 12 to 18 apply exactly as in clear weather', 'Sailing vessels always have priority', 'There is no stand-on vessel; every vessel proceeds at a safe speed with engines ready and acts in ample time'], answer: 3, explanation: 'Rules 12 to 18 require the vessels to be in sight of one another. Rule 19 applies to vessels not in sight of one another: safe speed, engines ready for immediate manoeuvre, early action, no stand-on vessel (F72, F73, T10).', difficulty: 2, part: 2, tags: ['rule-19', 'fog'] },
      { id: 'colregs-59', q: 'What fog signal does a power-driven vessel making way through the water give?', options: ['Two prolonged blasts at intervals of not more than 2 minutes', 'One prolonged blast at intervals of not more than 2 minutes', 'One prolonged and two short blasts at intervals of not more than 2 minutes', 'Five short blasts every minute'], answer: 1, explanation: 'Rule 35(a): one prolonged blast every 2 minutes at most. Two prolonged is a power-driven vessel underway but stopped (35(b)); one prolonged and two short is a sailing, fishing, NUC, RAM, constrained-by-draught or towing vessel (35(c)) (F76).', difficulty: 1, part: 2, tags: ['rule-35', 'fog', 'sound'] },
      { id: 'colregs-60', q: 'You must cross a traffic separation scheme in a 10 m motorboat. How should you cross?', options: ['Diagonally, following the general direction of the nearest lane', 'On a heading as nearly as practicable at right angles to the general direction of traffic flow', 'Inside the separation zone, where there is no traffic', 'Only after sounding five short blasts'], answer: 1, explanation: 'Rule 10(c): avoid crossing if possible; if you must, cross on a heading as nearly as practicable at right angles to the traffic flow. A vessel under 20 m must not impede power-driven vessels following a lane (Rule 10(j)) (F41, F43, S16).', difficulty: 2, part: 2, tags: ['rule-10', 'tss'] },
    ],
  });
})();
